          hasMore: (parseInt(offset) + dentists.length) < totalDentists
        },
        search: {
          latitude: lat,
          longitude: lon,
          radius: radiusKm,
          type: type || 'all',
          specialization: specialization || 'all'
        }
      }
    });

  } catch (error) {
    next(error);
  }
};

/**
 * Get dentist profile by ID
 */
export const getDentistById = async (req, res, next) => {
  try {
    const { id } = req.params;

    const dentistQuery = `
      SELECT 
        dp.id,
        u.id as user_id,
        u.name,
        u.email,
        u.phone_number,
        u.avatar_url,
        dp.title,
        dp.license_number,
        dp.license_issuing_body,
        dp.license_expiry_date,
        dp.registration_number,
        dp.primary_specialization as specialization,
        dp.education_qualification as education,
        dp.years_of_experience,
        dp.clinic_name,
        dp.clinic_address,
        dp.clinic_working_hours,
        dp.consultation_types,
        dp.services_offered,
        dp.consultation_fee,
        dp.accepts_insurance,
        dp.accepts_bpjs,
        dp.emergency_availability,
        dp.is_verified,
        dp.verification_date,
        dp.created_at,
        dp.updated_at,
        dp.clinic_id,
        dp.dentist_type
      FROM dentist_profiles dp
      JOIN users u ON dp.user_id = u.id
      WHERE dp.id = $1
    `;

    const result = await query(dentistQuery, [id]);

    if (result.rows.length === 0) {
      throw new APIError(ERROR_CODES.DENTIST_NOT_FOUND);
    }

    const dentist = result.rows[0];

    // Get clinics where this dentist works
    const clinicsQuery = `
      SELECT 
        cp.id,
        cp.brand_name as name,
        cp.street_address as address,
        cp.city,
        cp.phone as phone_number,
        cs.role,
        cs.is_active,
        cs.assigned_branch_id,
        cb.id as branch_id,
        cb.branch_name,
        cb.street_address as branch_address,
        cb.city as branch_city,
        cb.phone as branch_phone
      FROM clinic_staff cs
      JOIN clinic_profiles cp ON cs.clinic_profile_id = cp.id
      LEFT JOIN clinic_branches cb ON cs.assigned_branch_id = cb.id
      WHERE cs.user_id = $1
      ORDER BY cs.is_active DESC, cp.brand_name ASC
    `;

    let clinicsResult = await query(clinicsQuery, [dentist.user_id]);

    // Fallback: if no clinic_staff record but dentist.clinic_id exists, load clinic + main branch
    if (clinicsResult.rows.length === 0 && dentist.clinic_id) {
      const clinicProfileQuery = `
        SELECT 
          cp.id,
          cp.brand_name AS name,
          cp.street_address AS address,
          cp.city,
          cp.phone AS phone_number
        FROM clinic_profiles cp
        WHERE cp.id = $1
        LIMIT 1
      `;
      const clinicProfileResult = await query(clinicProfileQuery, [dentist.clinic_id]);

      if (clinicProfileResult.rows.length > 0) {
        const clinicRow = clinicProfileResult.rows[0];

        const branchQuery = `
          SELECT 
            cb.id AS branch_id,
            cb.branch_name,
            cb.street_address AS branch_address,
            cb.city AS branch_city,
            cb.phone AS branch_phone
          FROM clinic_branches cb
          WHERE cb.clinic_profile_id = $1
            AND cb.is_active = true
          ORDER BY cb.is_main_branch DESC, cb.id ASC
          LIMIT 1
        `;

        const branchResult = await query(branchQuery, [clinicRow.id]);
        const branchRow = branchResult.rows[0];

        clinicsResult = {
          rows: [
            {
              ...clinicRow,
              role: dentist.dentist_type === 'clinic' ? 'clinic_dentist' : 'independent',
              is_active: true,
              assigned_branch_id: branchRow?.branch_id || null,
              branch_id: branchRow?.branch_id || null,
              branch_name: branchRow?.branch_name || null,
              branch_address: branchRow?.branch_address || clinicRow.address,
              branch_city: branchRow?.branch_city || clinicRow.city,
              branch_phone: branchRow?.branch_phone || clinicRow.phone_number,
            },
          ],
        };
      }
    }

    res.json({
      success: true,
      data: {
        ...dentist,
        clinics: clinicsResult.rows
      }
    });
  } catch (error) {
    next(error);
  }
};

/**
 * Get dentist's schedule/availability
 */
export const getDentistSchedule = async (req, res, next) => {
  try {
    const { id } = req.params;
    const { date, clinicId } = req.query;

    // Verify dentist exists
    const dentistCheck = await query(
      'SELECT id, user_id FROM dentist_profiles WHERE id = $1',
      [id]
    );

    if (dentistCheck.rows.length === 0) {
      throw new APIError(ERROR_CODES.DENTIST_NOT_FOUND);
    }

    const dentist = dentistCheck.rows[0];

    // If specific clinic requested, verify dentist works there
    if (clinicId) {
      const staffCheck = await query(
        `SELECT id FROM clinic_staff 
         WHERE user_id = $1 AND clinic_profile_id = $2 AND role IN ('dentist', 'clinic_dentist') AND is_active = true`,
        [dentist.user_id, clinicId]
      );

      if (staffCheck.rows.length === 0) {
        throw new APIError({
          ...ERROR_CODES.DENTIST_NOT_FOUND,
          message: 'Dokter gigi tidak bekerja di klinik ini',
          messageEn: 'Dentist does not work at this clinic'
        });
      }
    }

    // Get dentist's working hours from clinic(s)
    const clinicsQuery = `
      SELECT 
        cp.id as clinic_id,
        cp.brand_name as clinic_name,
        cp.operating_hours
      FROM clinic_staff cs
      JOIN clinic_profiles cp ON cs.clinic_profile_id = cp.id
      WHERE cs.user_id = $1 
        AND cs.role IN ('dentist', 'clinic_dentist')
        AND cs.is_active = true
        ${clinicId ? 'AND cp.id = $2' : ''}
    `;

    const clinicsParams = clinicId ? [dentist.user_id, clinicId] : [dentist.user_id];
    const clinicsResult = await query(clinicsQuery, clinicsParams);

    if (clinicsResult.rows.length === 0) {
      return res.json({
        success: true,
        data: {
          dentist_id: id,
          date: date || 'all',
          clinics: [],
          message: 'Dokter gigi tidak memiliki jadwal aktif',
          messageEn: 'Dentist has no active schedule'
        }
      });
    }

    // For each clinic, get booked appointments on the requested date
    const schedules = await Promise.all(
      clinicsResult.rows.map(async (clinic) => {
        let bookedSlots = [];

        if (date) {
          const appointmentsQuery = `
            SELECT 
              appointment_date,
              appointment_time,
              duration_minutes
            FROM appointments
            WHERE dentist_id = $1 
              AND clinic_id = $2
              AND appointment_date = $3
              AND status NOT IN ('cancelled', 'rejected')
            ORDER BY appointment_time ASC
          `;

          const appointmentsResult = await query(appointmentsQuery, [
            id,
            clinic.clinic_id,
            date
          ]);

          bookedSlots = appointmentsResult.rows.map(apt => ({
            time: apt.appointment_time,
            duration: apt.duration_minutes
          }));
        }

        return {
          clinic_id: clinic.clinic_id,
          clinic_name: clinic.clinic_name,
          operating_hours: clinic.operating_hours,
          booked_slots: bookedSlots
        };
      })
    );

    res.json({
      success: true,
      data: {
        dentist_id: id,
        date: date || 'all',
        schedules
      }
    });
  } catch (error) {
    next(error);
  }
};

/**
 * Get available time slots for a dentist on a specific date
 */
export const getDentistAvailableSlots = async (req, res, next) => {
  try {
    const { id } = req.params;
    const { date, clinicId, duration = 30 } = req.query;

    console.log('📅 [getDentistAvailableSlots] Request:', { id, date, clinicId, duration });

    if (!date) {
      throw new APIError({
        ...ERROR_CODES.VALIDATION_ERROR,
        message: 'Tanggal harus diisi',
        messageEn: 'Date is required',
        fields: { date: 'Date parameter is required' }
      });
    }

    if (!clinicId) {
      throw new APIError({
        ...ERROR_CODES.VALIDATION_ERROR,
        message: 'Clinic ID harus diisi',
        messageEn: 'Clinic ID is required',
        fields: { clinicId: 'Clinic ID parameter is required' }
      });
    }

    // Verify dentist exists and works at this clinic, get consultation types
    const dentistCheck = await query(
      `SELECT dp.id, dp.user_id, dp.consultation_types
       FROM dentist_profiles dp
       JOIN clinic_staff cs ON dp.user_id = cs.user_id
         WHERE dp.id = $1 
         AND cs.clinic_profile_id = $2 
         AND cs.role IN ('dentist', 'clinic_dentist')
         AND cs.is_active = true`,
      [id, clinicId]
    );

    console.log('👨‍⚕️ [getDentistAvailableSlots] Dentist check:', dentistCheck.rows);

    if (dentistCheck.rows.length === 0) {
      throw new APIError(ERROR_CODES.DENTIST_NOT_FOUND);
    }

    // Get consultation types (default to onsite if not set)
    const consultationTypes = dentistCheck.rows[0].consultation_types || ['onsite'];
    console.log('💡 [getDentistAvailableSlots] Consultation types:', consultationTypes);

    // Normalize consultation types to match frontend expectations
    // Database might have: 'in-person', 'teleconsultation'
    // Frontend expects: 'onsite', 'virtual'
    const normalizedTypes = consultationTypes.map(type => {
      if (type === 'in-person') return 'onsite';
      if (type === 'teleconsultation') return 'virtual';
      return type; // Keep 'onsite' and 'virtual' as is
    });
    console.log('✨ [getDentistAvailableSlots] Normalized types:', normalizedTypes);

    // Get clinic branch operating hours
    // Note: clinicId from frontend is clinic_profile_id, we need to get the branch
    const clinicQuery = `
      SELECT cb.id as branch_id, cb.operating_hours, cb.branch_name, cb.is_main_branch
      FROM clinic_branches cb
      WHERE cb.clinic_profile_id = $1 
        AND cb.is_active = true
      ORDER BY cb.is_main_branch DESC, cb.id ASC
      LIMIT 1
    `;
    const clinicResult = await query(clinicQuery, [clinicId]);

    console.log('🏥 [getDentistAvailableSlots] Clinic result:', clinicResult.rows);

    if (clinicResult.rows.length === 0) {
      throw new APIError({
        ...ERROR_CODES.VALIDATION_ERROR,
        message: 'Klinik tidak ditemukan',
        messageEn: 'Clinic not found'
      });
    }

    const operatingHours = clinicResult.rows[0]?.operating_hours || {};
    console.log('⏰ [getDentistAvailableSlots] Operating hours:', operatingHours);

    // Get day of week from date
    const requestedDate = new Date(date);
    const dayOfWeek = requestedDate.toLocaleDateString('en-US', { weekday: 'long' }).toLowerCase();
    console.log('📆 [getDentistAvailableSlots] Day of week:', dayOfWeek);

    // Get operating hours for that day (format: "08:00-20:00" or "Closed")
    const daySchedule = operatingHours[dayOfWeek];
    console.log('🕐 [getDentistAvailableSlots] Day schedule:', daySchedule);

    if (!daySchedule || daySchedule.toLowerCase() === 'closed') {
      return res.json({
        success: true,
        data: {
          dentist_id: id,
          clinic_id: clinicId,
          date,
          slots: [],
          message: `Klinik tutup pada hari ${dayOfWeek}`,
          messageEn: `Clinic is closed on ${dayOfWeek}`
        }
      });
    }

    // Parse opening and closing times from format "08:00-20:00"
    if (!daySchedule.includes('-')) {
      console.warn('⚠️ Invalid schedule format:', daySchedule);
      return res.json({
        success: true,
        data: {
          dentist_id: id,
          clinic_id: clinicId,
          date,
          slots: [],
          message: `Format jadwal tidak valid`,
          messageEn: `Invalid schedule format`
        }
      });
    }

    const [openTime, closeTime] = daySchedule.split('-').map(t => t.trim());
    const [openHour, openMinute] = openTime.split(':').map(Number);
    const [closeHour, closeMinute] = closeTime.split(':').map(Number);

    console.log('🕐 [getDentistAvailableSlots] Hours:', { openHour, openMinute, closeHour, closeMinute });

    // Get the branch_id from the clinic result
    const branchId = clinicResult.rows[0].branch_id;
    console.log('🏢 [getDentistAvailableSlots] Using branch_id:', branchId);

    // Get all booked appointments for this dentist on this date
    const bookedQuery = `
      SELECT starts_at, ends_at
      FROM appointments
      WHERE dentist_id = $1 
        AND clinic_branch_id = $2
        AND DATE(starts_at) = $3
        AND status NOT IN ('cancelled', 'rejected')
      ORDER BY starts_at ASC
    `;
    const bookedResult = await query(bookedQuery, [id, branchId, date]);

    // Generate all possible time slots
    const slots = [];
    let currentHour = openHour;
    let currentMinute = openMinute;
    const slotDuration = parseInt(duration);

    while (
      currentHour < closeHour ||
      (currentHour === closeHour && currentMinute < closeMinute)
    ) {
      const slotTime = `${String(currentHour).padStart(2, '0')}:${String(currentMinute).padStart(2, '0')}`;

      // Check if this slot overlaps with any booked appointment
      const isBooked = bookedResult.rows.some(booking => {
        const bookingStart = new Date(booking.starts_at);
        const bookingEnd = new Date(booking.ends_at);

        // Create slot start and end times for comparison
        const slotStart = new Date(requestedDate);
        slotStart.setHours(currentHour, currentMinute, 0, 0);

        const slotEnd = new Date(slotStart);
        slotEnd.setMinutes(slotEnd.getMinutes() + slotDuration);

        // Check if slot overlaps with booking
        return (slotStart < bookingEnd && slotEnd > bookingStart);
      });

      // Check if slot end time is within operating hours
      const slotEndHour = Math.floor((currentMinute + slotDuration) / 60) + currentHour;
      const slotEndMinute = (currentMinute + slotDuration) % 60;
      const withinHours = slotEndHour < closeHour || 
                         (slotEndHour === closeHour && slotEndMinute <= closeMinute);

      if (!isBooked && withinHours) {
        // Generate slots for each consultation type the dentist supports
        normalizedTypes.forEach(type => {
          slots.push({
            id: `${date}-${slotTime}-${type}`,
            time: slotTime,
            startsAt: `${date}T${slotTime}:00`,
            duration: slotDuration,
            durationMinutes: slotDuration,
            type: type, // 'onsite' or 'virtual'
            isAvailable: true,
          });
        });
      }

      // Move to next slot
      currentMinute += slotDuration;
      if (currentMinute >= 60) {
        currentHour += Math.floor(currentMinute / 60);
        currentMinute = currentMinute % 60;
      }
    }

    console.log('✅ [getDentistAvailableSlots] Generated slots:', slots.length);

    res.json({
      success: true,
      data: {
        dentistId: id,
        clinicId: clinicId,
        branchId: branchId, // The actual branch ID for appointments
        branchName: clinicResult.rows[0].branch_name,
        date,
        dayOfWeek: dayOfWeek,
        operatingHours: daySchedule,
        slotDuration: slotDuration,
        slots: slots,
        availableSlots: slots, // Alias for compatibility
      }
    });
  } catch (error) {
    next(error);
  }
};

export const getDentistDirectory = async (req, res, next) => {
  try {
    const {
      specialization,
      dentistType,
      clinicId,
      verifiedOnly = 'false',
      limit = 50,
      offset = 0
    } = req.query;

    let sqlQuery = `
      SELECT 
        dp.id,
        u.id as user_id,
        u.name,
        u.email,
        u.avatar_url,
        dp.title,
        dp.license_number,
        dp.primary_specialization as specialization,
        dp.years_of_experience,
        dp.clinic_name,
        dp.clinic_address,
        dp.clinic_working_hours,
        dp.consultation_types,
        dp.services_offered,
        dp.consultation_fee,
        dp.accepts_insurance,
        dp.accepts_bpjs,
        dp.emergency_availability,
        dp.is_verified,
        dp.latitude,
        dp.longitude,
        dp.district,
        dp.province,
        dp.postal_code,
        dp.dentist_type,
        dp.clinic_id,
        dp.is_clinic_owner,
        dp.created_at
      FROM dentist_profiles dp
      JOIN users u ON dp.user_id = u.id
      WHERE 1=1
    `;

    const queryParams = [];
    let paramIndex = 1;

    if (specialization) {
      sqlQuery += ` AND dp.primary_specialization ILIKE $${paramIndex}`;
      queryParams.push(`%${specialization}%`);
      paramIndex++;
    }

    if (dentistType) {
      sqlQuery += ` AND dp.dentist_type = $${paramIndex}`;
      queryParams.push(dentistType);
      paramIndex++;
    }

    if (clinicId) {
      sqlQuery += ` AND dp.clinic_id = $${paramIndex}`;
      queryParams.push(BigInt(clinicId));
      paramIndex++;
    }

    if (String(verifiedOnly).toLowerCase() === 'true') {
      sqlQuery += ` AND dp.is_verified = true`;
    }

    sqlQuery += ` ORDER BY dp.is_verified DESC, dp.years_of_experience DESC, dp.created_at DESC`;
    sqlQuery += ` LIMIT $${paramIndex} OFFSET $${paramIndex + 1}`;
    queryParams.push(parseInt(limit), parseInt(offset));

    const result = await query(sqlQuery, queryParams);

    let countQuery = `SELECT COUNT(*) AS total FROM dentist_profiles dp WHERE 1=1`;
    const countParams = [];
    let countIndex = 1;

    if (specialization) {
      countQuery += ` AND dp.primary_specialization ILIKE $${countIndex}`;
      countParams.push(`%${specialization}%`);
      countIndex++;
    }

    if (dentistType) {
      countQuery += ` AND dp.dentist_type = $${countIndex}`;
      countParams.push(dentistType);
      countIndex++;
    }

    if (clinicId) {
      countQuery += ` AND dp.clinic_id = $${countIndex}`;
      countParams.push(BigInt(clinicId));
      countIndex++;
    }

    if (String(verifiedOnly).toLowerCase() === 'true') {
      countQuery += ` AND dp.is_verified = true`;
    }

    const countResult = await query(countQuery, countParams);
    const total = parseInt(countResult.rows[0].total, 10) || 0;

    const dentists = result.rows.map((row) => ({
      id: row.id,
      userId: row.user_id,
      name: row.name,
      email: row.email,
      avatarUrl: row.avatar_url,
      title: row.title,
      licenseNumber: row.license_number,
      specialization: row.specialization,
      yearsOfExperience: row.years_of_experience,
      clinicName: row.clinic_name,
      clinicAddress: row.clinic_address,
      workingHours: row.clinic_working_hours,
      consultationTypes: row.consultation_types,
      servicesOffered: row.services_offered,
      consultationFee: row.consultation_fee,
      acceptsInsurance: row.accepts_insurance,
      acceptsBpjs: row.accepts_bpjs,
      emergencyAvailable: row.emergency_availability,
      isVerified: row.is_verified,
      location: {
        latitude: row.latitude ? parseFloat(row.latitude) : null,
        longitude: row.longitude ? parseFloat(row.longitude) : null,
        district: row.district,
        province: row.province,
        postalCode: row.postal_code,
      },
      dentistType: row.dentist_type,
      clinicId: row.clinic_id,
      isClinicOwner: row.is_clinic_owner,
      createdAt: row.created_at,
    }));

    res.json({
      success: true,
      data: {
        dentists,
        pagination: {
          total,
          limit: parseInt(limit),
          offset: parseInt(offset),
          hasMore: offset + dentists.length < total,
        },
      },
    });
  } catch (error) {
    console.error('❌ Error fetching dentist directory:', error);
    next(error);
  }
};

import multer from 'multer';
import path from 'path';
import fs from 'fs';
import { getClient } from '../db.js';

// Simple error class for this controller
class ValidationError extends Error {
  constructor(message, statusCode = 400) {
    super(message);
    this.name = 'ValidationError';
    this.statusCode = statusCode;
  }
}

// Multer configuration for avatar upload
const storage = multer.diskStorage({
  destination: function (req, file, cb) {
    const uploadDir = 'uploads/avatars';
    // Create directory if it doesn't exist
    if (!fs.existsSync(uploadDir)) {
      fs.mkdirSync(uploadDir, { recursive: true });
    }
    cb(null, uploadDir);
  },
  filename: function (req, file, cb) {
    const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
    // Note: req.user might not be available yet in multer, so use generic naming
    cb(null, `patient-${uniqueSuffix}${path.extname(file.originalname)}`);
  }
});

const upload = multer({
  storage: storage,
  limits: {
    fileSize: 5 * 1024 * 1024 // 5MB limit
  },
  fileFilter: function (req, file, cb) {
    const allowedTypes = /jpeg|jpg|png/;
    const extname = allowedTypes.test(path.extname(file.originalname).toLowerCase());
    const mimetype = allowedTypes.test(file.mimetype);

    if (mimetype && extname) {
      return cb(null, true);
    } else {
      cb(new ValidationError('Only image files (JPEG, PNG) are allowed', 400));
    }
  }
});

/**
 * GET /v1/patient/profile
 * Get patient profile data
 * Auto-creates profile if it doesn't exist
 */
export const getPatientProfile = async (req, res, next) => {
  const client = await getClient();

  try {
    const userId = req.user.id;

    // Validate userId is for a patient
    const userCheck = await client.query(
      'SELECT id, name, email, phone_number, avatar_url, roles FROM users WHERE id = $1',
      [userId]
    );

    if (userCheck.rows.length === 0) {
      throw new ValidationError('User not found', 404);
    }

    if (!userCheck.rows[0].roles || !userCheck.rows[0].roles.includes('patient')) {
      throw new ValidationError('Access denied. Patient role required', 403);
    }

    // Check if profile exists
    let profileResult = await client.query(
      'SELECT * FROM patient_profiles WHERE user_id = $1',
      [userId]
    );

    // If profile doesn't exist, create it
    if (profileResult.rows.length === 0) {
      console.log(`📝 Creating new patient profile for user ${userId}`);

      profileResult = await client.query(
        `INSERT INTO patient_profiles (user_id, preferred_language)
         VALUES ($1, 'id')
         RETURNING *`,
        [userId]
      );
    }

    const userData = userCheck.rows[0];
    const profileData = profileResult.rows[0];

    res.status(200).json({
      status: 'success',
      data: {
        user: {
          id: userData.id,
          name: userData.name,
          email: userData.email,
          phoneNumber: userData.phone_number,
          avatarUrl: userData.avatar_url,
          roles: userData.roles
        },
        profile: {
          userId: profileData.user_id,
          dateOfBirth: profileData.date_of_birth,
          gender: profileData.gender,
          insuranceProvider: profileData.insurance_provider,
          insuranceNumber: profileData.insurance_number,
          insuranceMemberId: profileData.insurance_member_id,
          preferredLanguage: profileData.preferred_language || 'id',
          address: profileData.address,
          emergencyContact: profileData.emergency_contact,
          medicalDetails: profileData.medical_details,
          createdAt: profileData.created_at,
          updatedAt: profileData.updated_at
        }
      }
    });

  } catch (error) {
    console.error('❌ Get patient profile error:', error);
    next(error);
  } finally {
    client.release();
  }
};

/**
 * PUT /v1/patient/profile
 * Update patient profile with JSONB fields
 * 
 * Expected body:
 * {
 *   "name": "string (optional)",
 *   "phone_number": "string (optional)",
 *   "date_of_birth": "YYYY-MM-DD (optional)",
 *   "gender": "male|female|other (optional)",
 *   "address": {
 *     "line1": "string",
 *     "line2": "string (optional)",
 *     "city": "string",
 *     "province": "string",
 *     "postal_code": "string"
 *   },
 *   "emergency_contact": {
 *     "name": "string",
 *     "phone": "string",
 *     "relationship": "string"
 *   },
 *   "medical_details": {
 *     "allergies": ["string"],
 *     "current_medications": ["string"],
 *     "medical_conditions": ["string"],
 *     "blood_type": "string (optional)",
 *     "notes": "string (optional)"
 *   }
 * }
 */
export const updatePatientProfile = async (req, res, next) => {
  const client = await getClient();

  try {
    const userId = req.user.id;
    const {
      name,
      phone_number,
      date_of_birth,
      gender,
      address,
      emergency_contact,
      medical_details
    } = req.body;

    // Validate userId is for a patient
    const userCheck = await client.query(
      'SELECT roles FROM users WHERE id = $1',
      [userId]
    );

    if (userCheck.rows.length === 0) {
      throw new ValidationError('User not found', 404);
    }

    if (!userCheck.rows[0].roles || !userCheck.rows[0].roles.includes('patient')) {
      throw new ValidationError('Access denied. Patient role required', 403);
    }

    await client.query('BEGIN');

    // Update users table (name, phone_number)
    const userUpdateFields = [];
    const userUpdateValues = [];
    let userParamCount = 1;

    if (name !== undefined) {
      userUpdateFields.push(`name = $${userParamCount++}`);
      userUpdateValues.push(name);
    }

    if (phone_number !== undefined) {
      userUpdateFields.push(`phone_number = $${userParamCount++}`);
      userUpdateValues.push(phone_number);
    }

    if (userUpdateFields.length > 0) {
      userUpdateValues.push(userId);
      const userUpdateQuery = `
        UPDATE users 
        SET ${userUpdateFields.join(', ')}, updated_at = CURRENT_TIMESTAMP
        WHERE id = $${userParamCount}
        RETURNING id, name, email, phone_number, roles
      `;
      await client.query(userUpdateQuery, userUpdateValues);
    }

    // Update or create patient_profiles table
    const profileUpdateFields = [];
    const profileUpdateValues = [];
    let profileParamCount = 1;

    if (date_of_birth !== undefined) {
      profileUpdateFields.push(`date_of_birth = $${profileParamCount++}`);
      profileUpdateValues.push(date_of_birth);
    }

    if (gender !== undefined) {
      // Validate gender
      if (!['male', 'female', 'other'].includes(gender)) {
        throw new ValidationError('Invalid gender value. Must be male, female, or other', 400);
      }
      profileUpdateFields.push(`gender = $${profileParamCount++}`);
      profileUpdateValues.push(gender);
    }

    if (address !== undefined) {
      // Validate required address fields
      if (!address.line1 || !address.city || !address.province || !address.postal_code) {
        throw new ValidationError('Address must include line1, city, province, and postal_code', 400);
      }
      profileUpdateFields.push(`address = $${profileParamCount++}`);
      profileUpdateValues.push(JSON.stringify(address));
    }

    if (emergency_contact !== undefined) {
      // Validate required emergency contact fields
      if (!emergency_contact.name || !emergency_contact.phone || !emergency_contact.relationship) {
        throw new ValidationError('Emergency contact must include name, phone, and relationship', 400);
      }
      profileUpdateFields.push(`emergency_contact = $${profileParamCount++}`);
      profileUpdateValues.push(JSON.stringify(emergency_contact));
    }

    if (medical_details !== undefined) {
      // Validate medical details structure
      if (!Array.isArray(medical_details.allergies) || 
          !Array.isArray(medical_details.current_medications) || 
          !Array.isArray(medical_details.medical_conditions)) {
        throw new ValidationError('Medical details must include arrays for allergies, current_medications, and medical_conditions', 400);
      }
      profileUpdateFields.push(`medical_details = $${profileParamCount++}`);
      profileUpdateValues.push(JSON.stringify(medical_details));
    }

    let profileResult;
    if (profileUpdateFields.length > 0) {
      // Check if profile exists
      const profileExists = await client.query(
        'SELECT user_id FROM patient_profiles WHERE user_id = $1',
        [userId]
      );

      if (profileExists.rows.length > 0) {
        // Update existing profile
        profileUpdateValues.push(userId);
        const profileUpdateQuery = `
          UPDATE patient_profiles 
          SET ${profileUpdateFields.join(', ')}, updated_at = CURRENT_TIMESTAMP
          WHERE user_id = $${profileParamCount}
          RETURNING user_id, date_of_birth, gender, address, emergency_contact, medical_details
        `;
        profileResult = await client.query(profileUpdateQuery, profileUpdateValues);
      } else {
        // Create new profile
        const insertFields = ['user_id', ...profileUpdateFields.map(f => f.split(' = ')[0])];
        const insertValues = [userId, ...profileUpdateValues];
        const insertParams = insertValues.map((_, i) => `$${i + 1}`);

        const profileInsertQuery = `
          INSERT INTO patient_profiles (${insertFields.join(', ')})
          VALUES (${insertParams.join(', ')})
          RETURNING user_id, date_of_birth, gender, address, emergency_contact, medical_details
        `;
        profileResult = await client.query(profileInsertQuery, insertValues);
      }
    } else {
      // No profile updates, just fetch existing
      profileResult = await client.query(
        'SELECT user_id, date_of_birth, gender, address, emergency_contact, medical_details FROM patient_profiles WHERE user_id = $1',
        [userId]
      );
    }

    await client.query('COMMIT');

    // Fetch complete user data
    const userData = await client.query(
      'SELECT id, name, email, phone_number, roles FROM users WHERE id = $1',
      [userId]
    );

    const response = {
      user: userData.rows[0],
      profile: profileResult.rows[0] || null
    };

    res.status(200).json({
      status: 'success',
      message: 'Profile updated successfully',
      data: response
    });

  } catch (error) {
    await client.query('ROLLBACK');
    next(error);
  } finally {
    client.release();
  }
};

/**
 * POST /v1/patient/avatar
 * Upload patient avatar image
 * 
 * Expects multipart/form-data with:
 * - avatar: image file (JPEG/PNG, max 5MB)
 */
export const uploadPatientAvatar = [
  upload.single('avatar'),
  async (req, res, next) => {
    console.log('📤 Avatar upload started, file:', req.file);
    console.log('👤 User:', req.user);

    const client = await getClient();

    try {
      if (!req.file) {
        throw new ValidationError('No file uploaded', 400);
      }

      const userId = req.user.id;
      const avatarPath = `/uploads/avatars/${req.file.filename}`;

      // Validate userId is for a patient
      const userCheck = await client.query(
        'SELECT roles FROM users WHERE id = $1',
        [userId]
      );

      if (userCheck.rows.length === 0) {
        throw new ValidationError('User not found', 404);
      }

      if (!userCheck.rows[0].roles || !userCheck.rows[0].roles.includes('patient')) {
        throw new ValidationError('Access denied. Patient role required', 403);
      }

      await client.query('BEGIN');

      // Get old avatar from users table
      const oldAvatarResult = await client.query(
        'SELECT avatar_url FROM users WHERE id = $1',
        [userId]
      );

      const oldAvatarUrl = oldAvatarResult.rows[0]?.avatar_url;

      // Delete old avatar file if exists
      if (oldAvatarUrl) {
        const oldAvatarPath = path.join(process.cwd(), oldAvatarUrl);
        if (fs.existsSync(oldAvatarPath)) {
          fs.unlinkSync(oldAvatarPath);
        }
      }

      // Update avatar_url in users table (NOT patient_profiles)
      const result = await client.query(
        `UPDATE users 
         SET avatar_url = $1 
         WHERE id = $2 
         RETURNING id, avatar_url`,
        [avatarPath, userId]
      );

      await client.query('COMMIT');

      res.status(200).json({
        status: 'success',
        message: 'Avatar uploaded successfully',
        data: {
          avatar_url: result.rows[0].avatar_url
        }
      });

    } catch (error) {
      await client.query('ROLLBACK');

      // Log the actual error
      console.error('❌ Avatar upload error:', error);

      // Delete uploaded file if database update fails
      if (req.file) {
        const filePath = req.file.path;
        if (fs.existsSync(filePath)) {
          fs.unlinkSync(filePath);
        }
      }

      next(error);
    } finally {
      client.release();
    }
  }
];

