    }

    const updatedBranch = await prisma.clinicBranch.update({
      where: {
        id: BigInt(id),
        clinicProfileId: clinicProfile.id
      },
      data: updateData
    });

    res.json({
      message: 'Branch updated successfully',
      branch: updatedBranch
