]);

const upload = multer({
  storage: multer.memoryStorage(),
  limits: {
    fileSize: MAX_FILE_SIZE
  },
  fileFilter: (req, file, cb) => {
    if (!ALLOWED_MIME_TYPES.has(file.mimetype)) {
      const error = new Error('UNSUPPORTED_FILE_TYPE');
      error.status = 400;
      return cb(error);
    }
    return cb(null, true);
  }
});

