  try {
    const { id } = req.params;
    const existing = await pool.query(
      'SELECT * FROM dentist_services WHERE id = $1 AND dentist_profile_id = $2',
      [id, req.dentistProfileId]
    );

    if (!existing.rows.length) {
      return res.status(404).json({ error: 'Service not found' });
