        chatRoomId: room.id,
        userId: appointment.dentistId
      }
    },
    update: { role: 'dentist' },
    create: {
      chatRoomId: room.id,
      userId: appointment.dentistId,
      role: 'dentist',
      lastReadAt: now
    }
  });

  await client.chatRoomMember.upsert({
    where: {
