import { PrismaClient } from '@prisma/client';
import { emitChatMessage } from '../../sockets/chat.js';
import { logCommunicationEvent } from './logging.js';
import { recordCommunicationEvent } from '../communications.js';
import { parseParticipantIdentity } from './participantAccessService.js';
import { attachmentPresentationForMessage } from './attachmentStorageService.js';

const prisma = new PrismaClient();

/**
 * Handles Twilio Conversations webhooks (specifically onMessageAdded).
 * Synchronizes Twilio messages to the internal database.
 */
export async function handleChatMessageEvent(event) {
  const {
    EventType,
    ConversationSid,
    Author,
    Body,
    MessageSid,
    Attributes,
    DateCreated
  } = event;

  if (EventType !== 'onMessageAdded') {
    return { skipped: true, reason: 'unsupported_event_type' };
  }
  if (!MessageSid) {
    return { skipped: true, reason: 'missing_message_sid' };
  }

  // 1. Find the corresponding ChatRoom
  const chatRoom = await prisma.chatRoom.findUnique({
    where: { twilio_conversation_sid: ConversationSid },
    include: {
      appointment: {
        include: {
          communicationParticipants: true
        }
      },
      members: true
    }
  });

  if (!chatRoom) {
    logCommunicationEvent('message_sync_skipped', {
      reason: 'unknown_conversation',
      conversationSid: ConversationSid,
      messageSid: MessageSid
    }, 'warn');
    return { skipped: true, reason: 'unknown_conversation' };
  }

  // 2. Parse sender identity. Account users use numeric identities; verified guests use appointment-scoped participant identities.
  const parsedIdentity = parseParticipantIdentity(Author);
  if (!parsedIdentity) {
    logCommunicationEvent('message_sync_skipped', {
      reason: 'invalid_author',
      conversationSid: ConversationSid,
      messageSid: MessageSid,
      author: Author
    }, 'warn');
    return { skipped: true, reason: 'invalid_author' };
  }

  const participant = parsedIdentity.type === 'communication_participant'
    ? chatRoom.appointment.communicationParticipants.find((item) => (
        item.id === parsedIdentity.participantId
        && item.appointmentId === chatRoom.appointmentId
        && ['verified', 'joined'].includes(item.status)
      ))
    : null;
  const senderId = parsedIdentity.type === 'user' ? parsedIdentity.userId : participant?.userId || null;
  const isMember = senderId
    ? chatRoom.members.some((member) => member.userId === senderId)
      || chatRoom.appointment.communicationParticipants.some((item) => (
        item.userId === senderId && ['verified', 'joined'].includes(item.status)
      ))
    : Boolean(participant);
  if (!isMember || (parsedIdentity.type === 'communication_participant' && parsedIdentity.appointmentId !== chatRoom.appointmentId)) {
    logCommunicationEvent('permission_denied', {
      appointmentId: chatRoom.appointmentId,
      userId: senderId?.toString?.() ?? null,
      participantId: participant?.id,
      action: 'twilio_message_sync',
      messageSid: MessageSid
    }, 'warn');
    return { skipped: true, reason: 'sender_not_member' };
  }

  // 3. Parse attributes if any
  let attrs = {};
  try {
    attrs = Attributes ? JSON.parse(Attributes) : {};
  } catch (e) {
    logCommunicationEvent('message_attribute_parse_failed', {
      messageSid: MessageSid,
      conversationSid: ConversationSid
    }, 'warn');
  }

  const messageType = attrs.type === 'video_call' ? 'system' : (attrs.type || 'text');
  const fileSize = attrs.fileSizeBytes === undefined || attrs.fileSizeBytes === null
    ? null
    : BigInt(attrs.fileSizeBytes);
  const mediaRetentionUntil = attrs.mediaRetentionUntil ? new Date(attrs.mediaRetentionUntil) : null;
  const mediaDeletedAt = attrs.mediaDeletedAt ? new Date(attrs.mediaDeletedAt) : null;

  // 4. Upsert to prevent duplicate writes when Twilio retries or backend-originated sends already saved.
  const newMessage = await prisma.chatMessage.upsert({
    where: { twilioMessageSid: MessageSid },
    update: {
      message: Body || '',
      messageType,
      fileUrl: attrs.fileUrl,
      fileName: attrs.fileName,
      mimeType: attrs.mimeType,
      fileSizeBytes: fileSize,
      mediaRetentionUntil,
      storageProvider: attrs.storageProvider || null,
      storageBucket: attrs.storageBucket || null,
      storageObjectKey: attrs.storageObjectKey || null,
      mediaScanStatus: attrs.mediaScanStatus || null,
      mediaDeletedAt,
      mediaTombstoneReason: attrs.mediaTombstoneReason || null,
      senderCommunicationParticipantId: participant?.id || null,
      metadata: attrs
    },
    create: {
      chatRoomId: chatRoom.id,
      senderId,
      senderCommunicationParticipantId: participant?.id || null,
      message: Body || '',
      messageType,
      twilioMessageSid: MessageSid,
      createdAt: DateCreated ? new Date(DateCreated) : new Date(),
      fileUrl: attrs.fileUrl,
      fileName: attrs.fileName,
      mimeType: attrs.mimeType,
      fileSizeBytes: fileSize,
      mediaRetentionUntil,
      storageProvider: attrs.storageProvider || null,
      storageBucket: attrs.storageBucket || null,
      storageObjectKey: attrs.storageObjectKey || null,
      mediaScanStatus: attrs.mediaScanStatus || null,
      mediaDeletedAt,
      mediaTombstoneReason: attrs.mediaTombstoneReason || null,
      metadata: attrs
    },
    include: {
      sender: {
        select: { id: true, name: true, email: true, avatar_url: true }
      },
      senderCommunicationParticipant: {
        select: { id: true, displayName: true, email: true, role: true }
      }
    }
  });

  await recordCommunicationEvent({
    appointmentId: chatRoom.appointmentId,
    userId: senderId,
    actorRole: participant?.role || (senderId === chatRoom.appointment.dentistId ? 'dentist' : senderId === chatRoom.appointment.patientId ? 'patient' : null),
    eventType: attrs.type === 'video_call' && attrs.action ? `call_${attrs.action}` : 'message_webhook_synced',
    provider: 'twilio-conversations',
    providerEventId: MessageSid,
    resourceSid: ConversationSid,
    metadata: {
      messageType,
      action: attrs.action,
      chatRoomId: chatRoom.id.toString(),
      participantId: participant?.id || null
    }
  });

  const attachment = attachmentPresentationForMessage(newMessage);
  const serialized = {
    id: newMessage.id.toString(),
    chatRoomId: newMessage.chatRoomId.toString(),
    senderId: newMessage.senderId?.toString?.() ?? null,
    senderParticipantId: newMessage.senderCommunicationParticipantId || null,
    appointmentId: chatRoom.appointmentId.toString(),
    message: newMessage.message,
    messageType: newMessage.messageType,
    twilioMessageSid: newMessage.twilioMessageSid,
    fileUrl: attachment.fileUrl,
    fileName: newMessage.fileName,
    mimeType: newMessage.mimeType,
    fileSizeBytes: newMessage.fileSizeBytes?.toString?.() ?? null,
    mediaRetentionUntil: newMessage.mediaRetentionUntil,
    storageProvider: newMessage.storageProvider || newMessage.metadata?.storage || null,
    mediaScanStatus: newMessage.mediaScanStatus || newMessage.metadata?.scanStatus || null,
    mediaDeletedAt: newMessage.mediaDeletedAt,
    mediaTombstoneReason: attachment.tombstoneReason,
    attachmentAvailable: attachment.attachmentAvailable,
    metadata: newMessage.metadata || {},
    createdAt: newMessage.createdAt,
    sender: newMessage.sender ? {
      id: newMessage.sender.id.toString(),
      name: newMessage.sender.name,
      email: newMessage.sender.email,
      avatar: newMessage.sender.avatar_url
    } : newMessage.senderCommunicationParticipant ? {
      id: newMessage.senderCommunicationParticipant.id,
      name: newMessage.senderCommunicationParticipant.displayName,
      email: newMessage.senderCommunicationParticipant.email,
      role: newMessage.senderCommunicationParticipant.role,
      participantId: newMessage.senderCommunicationParticipant.id
    } : null
  };

  // 5. Notify connected Socket.io clients (for web-to-mobile or hybrid sync)
  emitChatMessage({
    channelName: chatRoom.channelName,
    message: serialized
  });

  logCommunicationEvent('message_synced', {
    appointmentId: chatRoom.appointmentId,
    chatRoomId: chatRoom.id,
    messageId: newMessage.id,
    twilioMessageSid: MessageSid,
    source: 'twilio_webhook'
  });

  return { success: true, messageId: newMessage.id.toString() };
}

import { PrismaClient } from '@prisma/client';
import { appointmentScopedRoomName } from './naming.js';
import {
  ensureCommunicationResourcesForAppointment,
  recordCommunicationEvent
} from '../communications.js';

const prisma = new PrismaClient();

const SECRET_KEYS = [
  'token',
  'jwt',
  'secret',
  'authToken',
  'apiKey',
  'apiKeySecret',
  'otp',
  'code',
  'inviteToken',
  'inviteTokenHash'
];

function toBigInt(value, fieldName = 'id') {
  try {
    return BigInt(value);
  } catch (_) {
    const error = new Error(`INVALID_${fieldName.toUpperCase()}`);
    error.status = 400;
    throw error;
  }
}

function asString(value) {
  return value?.toString?.() ?? null;
}

export function redactDiagnosticsMetadata(value) {
  if (Array.isArray(value)) return value.map(redactDiagnosticsMetadata);
  if (!value || typeof value !== 'object') return value;
  return Object.fromEntries(
    Object.entries(value).map(([key, item]) => {
      const lowered = key.toLowerCase();
      const shouldRedact = SECRET_KEYS.some((secretKey) => lowered.includes(secretKey.toLowerCase()));
      return [key, shouldRedact ? '[redacted]' : redactDiagnosticsMetadata(item)];
    })
  );
}

function serializeParticipant(participant) {
  return {
    id: participant.id,
    userId: asString(participant.userId),
    displayName: participant.displayName,
    role: participant.role,
    status: participant.status,
    invitedAt: participant.invitedAt,
    verifiedAt: participant.verifiedAt,
    joinedAt: participant.joinedAt,
    expiresAt: participant.expiresAt
  };
}

function serializeEvent(event) {
  return {
    id: event.id.toString(),
    appointmentId: event.appointmentId.toString(),
    actorUserId: asString(event.userId),
    actorRole: event.actorRole,
    eventType: event.eventType,
    provider: event.provider,
    providerSid: event.providerSid || event.resourceSid,
    providerEventId: event.providerEventId,
    occurredAt: event.occurredAt,
    metadata: redactDiagnosticsMetadata(event.metadata || {})
  };
}

function detectInconsistencies({ appointment, projection }) {
  const expectedName = appointmentScopedRoomName(appointment.id);
  const issues = [];
  if (appointment.chatRoom?.channelName && appointment.chatRoom.channelName !== expectedName) {
    issues.push({
      severity: 'error',
      code: 'chat_room_name_mismatch',
      message: 'Local chat room channel does not match appointment-scoped room naming.'
    });
  }
  if (appointment.videoRoomRef && appointment.videoRoomRef !== expectedName) {
    issues.push({
      severity: 'error',
      code: 'video_room_name_mismatch',
      message: 'Video room reference does not match appointment-scoped room naming.'
    });
  }
  if (appointment.commStatus === 'ready' && !appointment.chatRoom?.twilio_conversation_sid) {
    issues.push({
      severity: 'warning',
      code: 'missing_conversation_sid',
      message: 'Appointment is marked ready but no Twilio conversation SID is stored.'
    });
  }
  if (appointment.commStatus === 'ready' && !appointment.video_room_sid) {
    issues.push({
      severity: 'warning',
      code: 'missing_video_room_sid',
      message: 'Appointment is marked ready but no Twilio video room SID is stored.'
    });
  }
  if (projection.messagesMissingTwilioSid > 0) {
    issues.push({
      severity: 'warning',
      code: 'messages_missing_twilio_sid',
      message: 'Some local messages are missing a Twilio message SID.'
    });
  }
  if (projection.expiredAttachmentCount > 0) {
    issues.push({
      severity: 'info',
      code: 'expired_attachments_present',
      message: 'Some attachments are past retention and should render as placeholders.'
    });
  }
  return issues;
}

function bucketForInconsistencies(inconsistencies = []) {
  if (inconsistencies.some((issue) => issue.severity === 'error')) return 'error';
  if (inconsistencies.some((issue) => issue.severity === 'warning')) return 'warning';
  if (inconsistencies.length > 0) return 'info';
  return 'healthy';
}

async function getAppointmentOrThrow(appointmentId) {
  const appointment = await prisma.appointment.findUnique({
    where: { id: toBigInt(appointmentId, 'appointmentId') },
    include: {
      chatRoom: true,
      paymentIntents: {
        orderBy: { createdAt: 'desc' },
        take: 1
      },
      communicationParticipants: {
        orderBy: { createdAt: 'asc' }
      },
      videoSessions: {
        orderBy: { joinedAt: 'desc' },
        take: 20
      }
    }
  });
  if (!appointment) {
    const error = new Error('APPOINTMENT_NOT_FOUND');
    error.status = 404;
    throw error;
  }
  return appointment;
}

export async function getMessageProjectionStatus({ appointmentId }) {
  const appointment = await getAppointmentOrThrow(appointmentId);
  const chatRoomId = appointment.chatRoom?.id;
  const where = chatRoomId ? { chatRoomId } : { id: -1n };
  const now = new Date();

  const [
    localMessageCount,
    twilioSyncedMessageCount,
    messagesMissingTwilioSid,
    attachmentCount,
    expiredAttachmentCount,
    deletedAttachmentCount
  ] = await Promise.all([
    prisma.chatMessage.count({ where }),
    prisma.chatMessage.count({ where: { ...where, twilioMessageSid: { not: null } } }),
    prisma.chatMessage.count({ where: { ...where, twilioMessageSid: null } }),
    prisma.chatMessage.count({ where: { ...where, messageType: 'file' } }),
    prisma.chatMessage.count({
      where: {
        ...where,
        messageType: 'file',
        mediaRetentionUntil: { lt: now }
      }
    }),
    prisma.chatMessage.count({
      where: {
        ...where,
        messageType: 'file',
        OR: [
          { fileUrl: null },
          { metadata: { path: ['deleted'], equals: true } }
        ]
      }
    })
  ]);

  return {
    appointmentId: appointment.id.toString(),
    chatRoomId: asString(chatRoomId),
    conversationSid: appointment.chatRoom?.twilio_conversation_sid || null,
    localMessageCount,
    twilioSyncedMessageCount,
    messagesMissingTwilioSid,
    attachmentCount,
    expiredAttachmentCount,
    deletedAttachmentCount,
    retentionRespected: expiredAttachmentCount === 0,
    sourceOfTruth: 'local_db_chat_messages'
  };
}

export async function getCommunicationTimeline({ appointmentId, limit = 100 }) {
  const apptId = toBigInt(appointmentId, 'appointmentId');
  await prisma.appointment.findUniqueOrThrow({ where: { id: apptId }, select: { id: true } }).catch(() => {
    const error = new Error('APPOINTMENT_NOT_FOUND');
    error.status = 404;
    throw error;
  });
  const events = await prisma.communicationEvent.findMany({
    where: { appointmentId: apptId },
    orderBy: { occurredAt: 'asc' },
    take: Math.min(Number(limit) || 100, 250)
  });
  return {
    appointmentId: apptId.toString(),
    events: events.map(serializeEvent)
  };
}

export async function getAppointmentDiagnostics({ appointmentId }) {
  const appointment = await getAppointmentOrThrow(appointmentId);
  const webhookProviderWhere = { provider: { in: ['twilio', 'twilio-conversations', 'twilio-video', 'midtrans'] } };
  const appointmentWebhookIds = [
    appointment.chatRoom?.twilio_conversation_sid,
    appointment.video_room_sid,
    appointment.videoRoomRef
  ].filter(Boolean);
  const appointmentWebhookWhere = appointmentWebhookIds.length
    ? {
        AND: [
          webhookProviderWhere,
          {
            OR: [
              { resourceId: { in: appointmentWebhookIds } },
              { correlationId: { in: appointmentWebhookIds } }
            ]
          }
        ]
      }
    : webhookProviderWhere;
  const [projection, timeline, lastReceipts, lastOutbox, processedReceiptCount, mismatchCount, invalidSignatureCount, provisioningRetryCount] = await Promise.all([
    getMessageProjectionStatus({ appointmentId: appointment.id }),
    getCommunicationTimeline({ appointmentId: appointment.id, limit: 50 }),
    prisma.webhookReceipt.findMany({
      where: appointmentWebhookWhere,
      orderBy: { receivedAt: 'desc' },
      take: 10
    }),
    prisma.domainEventOutbox.findMany({
      where: {
        OR: [
          { aggregateType: 'appointment', aggregateId: appointment.id.toString() },
          { payload: { path: ['appointmentId'], equals: appointment.id.toString() } }
        ]
      },
      orderBy: { createdAt: 'desc' },
      take: 10
    }),
    prisma.webhookReceipt.count({ where: { ...appointmentWebhookWhere, status: 'processed' } }),
    prisma.webhookReceipt.count({ where: { ...appointmentWebhookWhere, lastError: 'WEBHOOK_REPLAY_PAYLOAD_MISMATCH' } }),
    prisma.webhookReceipt.count({ where: { ...appointmentWebhookWhere, status: 'ignored', lastError: 'TWILIO_SIGNATURE_INVALID' } }),
    prisma.communicationEvent.count({
      where: {
        appointmentId: appointment.id,
        eventType: 'provisioning_retry'
      }
    })
  ]);

  const expectedRoomName = appointmentScopedRoomName(appointment.id);
  const latestPayment = appointment.paymentIntents?.[0] || null;
  const inconsistencies = detectInconsistencies({ appointment, projection });

  return {
    appointmentId: appointment.id.toString(),
    expectedRoomName,
    noSecretsDisplayed: true,
    status: {
      appointment: appointment.status,
      payment: latestPayment?.status || 'unknown',
      communications: appointment.commStatus
    },
    readiness: {
      tokenReady: appointment.commStatus === 'ready',
      chatReady: Boolean(appointment.chatRoom?.twilio_conversation_sid),
      videoReady: Boolean(appointment.video_room_sid),
      roomNameStable: appointment.videoRoomRef === expectedRoomName
        && (!appointment.chatRoom?.channelName || appointment.chatRoom.channelName === expectedRoomName)
    },
    resources: {
      chatRoomId: asString(appointment.chatRoom?.id),
      conversationSid: appointment.chatRoom?.twilio_conversation_sid || null,
      chatChannelName: appointment.chatRoom?.channelName || null,
      videoRoomName: appointment.videoRoomRef || null,
      videoRoomSid: appointment.video_room_sid || null
    },
    operational: {
      bucket: bucketForInconsistencies(inconsistencies),
      processedReceiptCount,
      payloadMismatchCount: mismatchCount,
      invalidSignatureCount,
      provisioningRetryCount,
      attachmentRetentionRespected: projection.retentionRespected
    },
    participants: [
      { role: 'dentist', userId: appointment.dentistId.toString(), status: 'assigned' },
      { role: 'patient', userId: appointment.patientId.toString(), status: 'assigned' },
      ...appointment.communicationParticipants.map(serializeParticipant)
    ],
    projection,
    videoSessions: appointment.videoSessions.map((session) => ({
      id: session.id.toString(),
      userId: asString(session.userId),
      actorRole: session.actorRole,
      joinedAt: session.joinedAt,
      leftAt: session.leftAt,
      durationSeconds: session.durationSeconds
    })),
    webhookReceipts: lastReceipts.map((receipt) => ({
      id: receipt.id.toString(),
      provider: receipt.provider,
      source: receipt.source,
      eventType: receipt.eventType,
      resourceId: receipt.resourceId,
      status: receipt.status,
      attempts: receipt.attempts,
      receivedAt: receipt.receivedAt,
      processedAt: receipt.processedAt,
      lastError: receipt.lastError
    })),
    outbox: lastOutbox.map((event) => ({
      id: event.id.toString(),
      eventType: event.eventType,
      aggregateType: event.aggregateType,
      aggregateId: event.aggregateId,
      status: event.status,
      attempts: event.attempts,
      availableAt: event.availableAt,
      publishedAt: event.publishedAt,
      lastError: event.lastError
    })),
    timeline: timeline.events,
    inconsistencies
  };
}

export async function listOperationalCommunicationDiagnostics({
  status,
  bucket,
  limit = 25
} = {}) {
  const take = Math.min(Math.max(Number(limit) || 25, 1), 100);
  const where = {};
  if (status && status !== 'all') {
    if (['ready', 'pending', 'provisioning_failed'].includes(status)) {
      where.commStatus = status;
    } else {
      where.status = status;
    }
  }

  const appointments = await prisma.appointment.findMany({
    where,
    orderBy: { updatedAt: 'desc' },
    take,
    include: {
      chatRoom: true,
      paymentIntents: {
        orderBy: { createdAt: 'desc' },
        take: 1
      },
      communicationParticipants: true
    }
  });

  const rows = [];
  for (const appointment of appointments) {
    const projection = await getMessageProjectionStatus({ appointmentId: appointment.id });
    const inconsistencies = detectInconsistencies({ appointment, projection });
    const rowBucket = bucketForInconsistencies(inconsistencies);
    if (bucket && bucket !== 'all' && rowBucket !== bucket) continue;
    rows.push({
      appointmentId: appointment.id.toString(),
      status: appointment.status,
      commStatus: appointment.commStatus,
      paymentStatus: appointment.paymentIntents?.[0]?.status || 'unknown',
      expectedRoomName: appointmentScopedRoomName(appointment.id),
      conversationSidPresent: Boolean(appointment.chatRoom?.twilio_conversation_sid),
      videoRoomSidPresent: Boolean(appointment.video_room_sid),
      participantCount: appointment.communicationParticipants.length,
      localMessageCount: projection.localMessageCount,
      attachmentCount: projection.attachmentCount,
      bucket: rowBucket,
      inconsistencyCodes: inconsistencies.map((issue) => issue.code),
      updatedAt: appointment.updatedAt
    });
  }

  const replayCounters = await prisma.webhookReceipt.groupBy({
    by: ['status'],
    where: { provider: { in: ['twilio', 'twilio-conversations', 'twilio-video', 'midtrans'] } },
    _count: { _all: true }
  });
  const provisioningRetries = await prisma.communicationEvent.count({
    where: { eventType: 'provisioning_retry' }
  });

  return {
    filters: {
      status: status || 'all',
      bucket: bucket || 'all',
      limit: take
    },
    replayCounters: Object.fromEntries(replayCounters.map((item) => [item.status, item._count._all])),
    provisioningRetries,
    rows
  };
}

export async function exportCommunicationAudit({ appointmentId, format = 'json' }) {
  const timeline = await getCommunicationTimeline({ appointmentId, limit: 250 });
  const safeEvents = timeline.events.map((event) => ({
    appointmentId: event.appointmentId,
    occurredAt: event.occurredAt,
    eventType: event.eventType,
    actorRole: event.actorRole,
    actorUserId: event.actorUserId,
    provider: event.provider,
    providerSid: event.providerSid,
    metadata: redactDiagnosticsMetadata(event.metadata || {})
  }));

  if (format === 'csv') {
    const headers = ['appointmentId', 'occurredAt', 'eventType', 'actorRole', 'actorUserId', 'provider', 'providerSid', 'metadata'];
    const escapeCsv = (value) => `"${String(value ?? '').replace(/"/g, '""')}"`;
    return {
      appointmentId: timeline.appointmentId,
      contentType: 'text/csv',
      body: [
        headers.join(','),
        ...safeEvents.map((event) => headers.map((key) => escapeCsv(
          key === 'metadata' ? JSON.stringify(event.metadata || {}) : event[key]
        )).join(','))
      ].join('\n')
    };
  }

  return {
    appointmentId: timeline.appointmentId,
    contentType: 'application/json',
    body: JSON.stringify({ events: safeEvents }, null, 2)
  };
}

export async function reconcileAppointmentCommunications({ appointmentId, user }) {
  const appointment = await getAppointmentOrThrow(appointmentId);
  const latestPayment = appointment.paymentIntents?.[0] || null;
  const paymentReady = ['confirmed', 'completed'].includes(appointment.status)
    || ['settled', 'paid', 'capture', 'success'].includes(latestPayment?.status);

  await recordCommunicationEvent({
    appointmentId: appointment.id,
    userId: user?.id || null,
    actorRole: 'admin',
    eventType: 'diagnostics_check_executed',
    metadata: {
      command: 'reconcile',
      paymentReady,
      commStatus: appointment.commStatus
    }
  });

  if (!paymentReady || appointment.status === 'cancelled') {
    return {
      appointmentId: appointment.id.toString(),
      changed: false,
      skipped: true,
      reason: 'appointment_not_safe_for_reconcile',
      diagnostics: await getAppointmentDiagnostics({ appointmentId: appointment.id })
    };
  }

  const resources = await ensureCommunicationResourcesForAppointment({
    appointmentId: appointment.id,
    reason: 'admin_reconcile'
  });

  await recordCommunicationEvent({
    appointmentId: appointment.id,
    userId: user?.id || null,
    actorRole: 'admin',
    eventType: 'diagnostics_reconcile_executed',
    metadata: {
      conversationSid: resources.conversationSid,
      videoRoomSid: resources.videoRoomSid,
      roomName: resources.roomName
    }
  });

  return {
    appointmentId: appointment.id.toString(),
    changed: true,
    skipped: false,
    resources: {
      conversationSid: resources.conversationSid,
      videoRoomSid: resources.videoRoomSid,
      roomName: resources.roomName
    },
    diagnostics: await getAppointmentDiagnostics({ appointmentId: appointment.id })
  };
}

export const __testables = {
  bucketForInconsistencies,
  detectInconsistencies,
  redactDiagnosticsMetadata,
  serializeEvent
};

import { PrismaClient } from '@prisma/client';
import { parseAppointmentIdFromRoomName } from './naming.js';
import { logCommunicationEvent } from './logging.js';
import {
  disconnectVideoParticipantForIdentity,
  recordCommunicationEvent
} from '../communications.js';
import {
  markCommunicationParticipantJoinedFromIdentity,
  parseParticipantIdentity
} from './participantAccessService.js';

const prisma = new PrismaClient();
const OBSERVER_PUBLISH_EVENTS = new Set([
  'track-published',
  'track-added',
  'track-started'
]);

function parseVideoAppointment(event) {
  const appointmentId = parseAppointmentIdFromRoomName(event.RoomName);
  if (!appointmentId) {
    return null;
  }
  return BigInt(appointmentId);
}

function eventOccurredAt(event) {
  const parsed = event.Timestamp ? new Date(event.Timestamp) : new Date();
  return Number.isNaN(parsed.getTime()) ? new Date() : parsed;
}

async function recordVideoEvent(event, eventType, appointmentId, userId = null, metadata = {}, actorRole = null) {
  const providerEventId = [
    event.RoomSid,
    event.StatusCallbackEvent,
    event.ParticipantSid || event.ParticipantIdentity || '',
    event.TrackSid || event.TrackName || event.TrackKind || '',
    event.Timestamp || ''
  ].filter(Boolean).join(':');

  await recordCommunicationEvent({
    appointmentId,
    userId,
    actorRole,
    eventType,
    provider: 'twilio-video',
    providerEventId,
    resourceSid: event.RoomSid,
    metadata: {
      roomName: event.RoomName,
      participantSid: event.ParticipantSid,
      participantIdentity: event.ParticipantIdentity,
      ...metadata
    },
    occurredAt: eventOccurredAt(event)
  });
}

function isObserverTrackPublishEvent(event, parsedIdentity) {
  return parsedIdentity?.type === 'clinic_observer'
    && OBSERVER_PUBLISH_EVENTS.has(event.StatusCallbackEvent)
    && Boolean(event.TrackSid || event.TrackKind);
}

function videoSessionActorRole(parsedIdentity, externalParticipant = null) {
  if (parsedIdentity?.type === 'clinic_observer') return 'observer';
  if (parsedIdentity?.type === 'communication_participant') {
    return externalParticipant?.role || parsedIdentity.role || 'participant';
  }
  return parsedIdentity?.role || 'participant';
}

async function handleObserverPublishViolation(event, appointmentId, parsedIdentity) {
  const metadata = {
    roomName: event.RoomName,
    roomSid: event.RoomSid,
    participantSid: event.ParticipantSid,
    trackSid: event.TrackSid,
    trackKind: event.TrackKind,
    statusCallbackEvent: event.StatusCallbackEvent,
    action: 'auto_disconnect_attempted'
  };

  await recordVideoEvent(
    event,
    'clinic_observer_publish_violation',
    appointmentId,
    parsedIdentity.userId,
    metadata,
    'observer'
  );

  let disconnected = false;
  try {
    const result = await disconnectVideoParticipantForIdentity({
      appointmentId,
      identity: event.ParticipantIdentity,
      reason: 'clinic_observer_publish_violation'
    });
    disconnected = Boolean(result?.disconnected);
  } catch (error) {
    logCommunicationEvent('clinic_observer_publish_violation_disconnect_failed', {
      appointmentId,
      roomName: event.RoomName,
      roomSid: event.RoomSid,
      error: error.message
    }, 'warn');
  }

  logCommunicationEvent('clinic_observer_publish_violation', {
    appointmentId,
    roomName: event.RoomName,
    roomSid: event.RoomSid,
    userId: parsedIdentity.userId,
    trackSid: event.TrackSid,
    disconnected
  }, 'warn');

  return { processed: true, violation: true, disconnected };
}

export async function handleVideoEvent(event) {
  const {
    StatusCallbackEvent,
    RoomSid,
    RoomName,
    RoomDuration,
    ParticipantIdentity,
  } = event;

  const appointmentId = parseVideoAppointment(event);
  if (!appointmentId) {
    return { skipped: true, reason: 'unknown_room_name' };
  }

  switch (StatusCallbackEvent) {
    case 'room-created': {
      await recordVideoEvent(event, 'room_created', appointmentId);
      logCommunicationEvent('room_ensured', { appointmentId, roomName: RoomName, roomSid: RoomSid });
      return { processed: true };
    }

    case 'room-ended': {
      const appointment = await prisma.appointment.findUnique({
        where: { id: appointmentId }
      });

      if (appointment && appointment.status === 'confirmed') {
        await prisma.appointment.update({
          where: { id: appointmentId },
          data: { status: 'completed' }
        });

        await prisma.appointmentStatusHistory.create({
          data: {
            appointmentId,
            newStatus: 'completed',
            previousStatus: 'confirmed',
            reason: 'video_session_ended',
            metadata: {
              roomSid: RoomSid,
              durationSeconds: Number(RoomDuration || 0)
            }
          }
        });

        await prisma.domainEventOutbox.create({
          data: {
            eventType: 'video_session_ended',
            aggregateType: 'appointment',
            aggregateId: appointmentId.toString(),
            payload: {
              appointmentId: appointmentId.toString(),
              roomSid: RoomSid,
              durationSeconds: Number(RoomDuration || 0)
            }
          }
        });
      }

      await recordVideoEvent(event, 'room_ended', appointmentId, null, {
        durationSeconds: Number(RoomDuration || 0)
      });
      logCommunicationEvent('room_ended', {
        appointmentId,
        roomName: RoomName,
        roomSid: RoomSid,
        durationSeconds: Number(RoomDuration || 0)
      });

      return { processed: true };
    }

    case 'participant-connected': {
      if (!ParticipantIdentity) return { skipped: true, reason: 'missing_participant_identity' };
      const parsedIdentity = parseParticipantIdentity(ParticipantIdentity);
      if (!parsedIdentity) return { skipped: true, reason: 'invalid_participant_identity' };
      const joinedAt = eventOccurredAt(event);
      const userId = ['user', 'clinic_observer'].includes(parsedIdentity?.type) ? parsedIdentity.userId : null;
      const externalParticipant = parsedIdentity?.type === 'communication_participant'
        ? await markCommunicationParticipantJoinedFromIdentity({
            appointmentId,
            identity: ParticipantIdentity,
            joinedAt
          })
        : null;
      const actorRole = videoSessionActorRole(parsedIdentity, externalParticipant);

      if (userId) {
        const existing = await prisma.videoSession.findFirst({
          where: { appointmentId, userId, leftAt: null }
        });

        if (!existing) {
          await prisma.videoSession.create({
            data: {
              appointmentId,
              userId,
              actorRole,
              joinedAt
            }
          });
        } else {
          await prisma.videoSession.update({
            where: { id: existing.id },
            data: { joinedAt, actorRole }
          });
        }
      }

      await recordVideoEvent(
        event,
        parsedIdentity?.type === 'clinic_observer' ? 'clinic_observer_joined' : 'participant_joined',
        appointmentId,
        userId,
        { participantId: externalParticipant?.id || null },
        actorRole
      );
      logCommunicationEvent('room_joined', {
        appointmentId,
        roomName: RoomName,
        roomSid: RoomSid,
        userId,
        actorRole,
        participantId: externalParticipant?.id || null
      });
      return { processed: true };
    }

    case 'participant-disconnected': {
      if (!ParticipantIdentity) return { skipped: true, reason: 'missing_participant_identity' };
      const parsedIdentity = parseParticipantIdentity(ParticipantIdentity);
      if (!parsedIdentity) return { skipped: true, reason: 'invalid_participant_identity' };
      const userId = ['user', 'clinic_observer'].includes(parsedIdentity?.type) ? parsedIdentity.userId : null;
      const externalParticipant = parsedIdentity?.type === 'communication_participant'
        ? await prisma.appointmentCommunicationParticipant.findUnique({
            where: { id: parsedIdentity.participantId }
          }).catch(() => null)
        : null;
      const actorRole = videoSessionActorRole(parsedIdentity, externalParticipant);
      const session = userId
        ? await prisma.videoSession.findFirst({
            where: {
              appointmentId,
              userId,
              leftAt: null
            },
            orderBy: { joinedAt: 'desc' }
          })
        : null;

      let durationSeconds = null;
      if (session) {
        const leftAt = eventOccurredAt(event);
        durationSeconds = Math.max(0, Math.round((leftAt.getTime() - session.joinedAt.getTime()) / 1000));

        await prisma.videoSession.update({
          where: { id: session.id },
          data: {
            leftAt,
            durationSeconds
          }
        });
      }

      await recordVideoEvent(
        event,
        parsedIdentity?.type === 'clinic_observer' ? 'clinic_observer_left' : 'participant_disconnected',
        appointmentId,
        userId,
        {
          durationSeconds,
          participantId: externalParticipant?.id || null
        },
        actorRole
      );
      logCommunicationEvent('room_left', {
        appointmentId,
        roomName: RoomName,
        roomSid: RoomSid,
        userId,
        actorRole,
        participantId: externalParticipant?.id || null,
        durationSeconds
      });
      return { processed: true };
    }

    case 'participant-reconnected': {
      if (!ParticipantIdentity) return { skipped: true, reason: 'missing_participant_identity' };
      const parsedIdentity = parseParticipantIdentity(ParticipantIdentity);
      if (!parsedIdentity) return { skipped: true, reason: 'invalid_participant_identity' };
      const userId = ['user', 'clinic_observer'].includes(parsedIdentity?.type) ? parsedIdentity.userId : null;
      await recordVideoEvent(
        event,
        parsedIdentity?.type === 'clinic_observer' ? 'clinic_observer_reconnected' : 'participant_reconnected',
        appointmentId,
        userId,
        {},
        parsedIdentity?.role || null
      );
      logCommunicationEvent('participant_reconnected', {
        appointmentId,
        roomName: RoomName,
        roomSid: RoomSid,
        userId,
        actorRole: parsedIdentity?.role || null
      });
      return { processed: true };
    }

    default:
      if (ParticipantIdentity) {
        const parsedIdentity = parseParticipantIdentity(ParticipantIdentity);
        if (isObserverTrackPublishEvent(event, parsedIdentity)) {
          return handleObserverPublishViolation(event, appointmentId, parsedIdentity);
        }
      }
      await recordVideoEvent(event, 'video_webhook_ignored', appointmentId, null, {
        statusCallbackEvent: StatusCallbackEvent
      });
      return { skipped: true, reason: 'unsupported_event_type' };
  }
}

