import { resolvePaymentOwner } from './ownership.js';

function calculateFinancialSplit(amount, ownerType = 'dentist') {
  const grossAmount = Number.isFinite(Number(amount)) ? Math.max(0, Math.round(Number(amount))) : 0;
  const platformFee = Math.round(grossAmount * 0.1);
  if (ownerType === 'clinic') {
    const dentistShare = Math.round(grossAmount * 0.3);
    const clinicShare = grossAmount - platformFee - dentistShare;
    return { platformFee, dentistShare, clinicShare, grandTotal: grossAmount };
  }
  return {
    platformFee,
    dentistShare: grossAmount - platformFee,
    clinicShare: 0,
    grandTotal: grossAmount
  };
}

function getTreatmentPlanIdFromIntent(paymentIntent = {}) {
  const metadata = paymentIntent.metadata && typeof paymentIntent.metadata === 'object' && !Array.isArray(paymentIntent.metadata)
    ? paymentIntent.metadata
    : {};
  const raw = metadata.treatmentPlanId || metadata.treatment_plan_id;
  if (!raw) return null;
  try {
    return BigInt(raw);
  } catch (_error) {
    return null;
  }
}

function normalizeLineItems(items = []) {
  return items
    .map((item) => ({
      description: item.name || item.description || 'Consultation',
      quantity: Number.isFinite(item.quantity) ? item.quantity : parseInt(item.quantity || 1, 10),
      unitPrice: Number.isFinite(item.price) ? item.price : parseInt(item.price || 0, 10)
    }))
    .map((item) => ({
      ...item,
      total: (item.unitPrice || 0) * (item.quantity || 0)
    }));
}

export async function ensureInvoiceForPaymentIntent({
  tx,
  paymentIntent,
  appointment,
  patient,
  items = []
}) {
  if (!tx || !paymentIntent) return null;

  const existing = await tx.invoice.findFirst({
    where: { paymentIntentId: paymentIntent.id }
  });
  const treatmentPlanId = getTreatmentPlanIdFromIntent(paymentIntent);
  if (existing) {
    if (treatmentPlanId && !existing.treatmentPlanId) {
      return tx.invoice.update({
        where: { id: existing.id },
        data: {
          treatmentPlanId,
          metadata: {
            ...(existing.metadata || {}),
            treatmentPlanId: treatmentPlanId.toString(),
            source: existing.metadata?.source || 'payment_intent'
          }
        }
      });
    }
    return existing;
  }

  const lineItems = items && items.length > 0
    ? normalizeLineItems(items)
    : [
        {
          description: appointment?.reason || 'Dental Consultation',
          quantity: 1,
          unitPrice: paymentIntent.amount,
          total: paymentIntent.amount
        }
      ];
  const subtotal = lineItems.reduce((sum, item) => sum + item.total, 0);
  const total = subtotal;

  const owner = resolvePaymentOwner(appointment || {});
  const split = calculateFinancialSplit(total, owner.ownerType);
  const reference = `INV-${String(paymentIntent.id).padStart(6, '0')}`;
  const issuedAt = new Date();

  let issuerType = owner.ownerType;
  let issuerName = 'Serene Clinic';
  let issuerEmail = 'billing@serene.test';
  let issuerPhone = '0812345678';
  let issuerAddress = 'Jakarta, Indonesia';
  let issuerTaxId = 'TAX-000';
  let issuerSnapshot = {};

  if (owner.ownerType === 'clinic' && owner.ownerClinicId) {
    const clinic = await tx.clinicProfile.findUnique({
      where: { id: owner.ownerClinicId }
    });
    if (clinic) {
      issuerName = clinic.legalName || clinic.name || issuerName;
      issuerEmail = clinic.email || issuerEmail;
      issuerPhone = clinic.phone || issuerPhone;
      issuerAddress = clinic.streetAddress || issuerAddress;
      issuerTaxId = clinic.npwpNumber || issuerTaxId;
      issuerSnapshot = {
        id: clinic.id.toString(),
        legalName: clinic.legalName,
        brandName: clinic.brandName,
        facilityType: clinic.facilityType,
        streetAddress: clinic.streetAddress,
        city: clinic.city,
        province: clinic.province,
        postalCode: clinic.postalCode,
        phone: clinic.phone,
        email: clinic.email,
        npwpNumber: clinic.npwpNumber
      };
    }
  } else if (owner.ownerDentistId) {
    const dentist = await tx.user.findUnique({
      where: { id: owner.ownerDentistId },
      include: { dentistProfile: true }
    });
    if (dentist) {
      const profile = dentist.dentistProfile?.[0];
      issuerName = dentist.name || issuerName;
      issuerEmail = dentist.email || issuerEmail;
      issuerPhone = dentist.phone_number || issuerPhone;
      issuerAddress = profile?.clinicAddress || issuerAddress;
      issuerTaxId = profile?.registrationNumber || issuerTaxId;
      issuerSnapshot = {
        userId: dentist.id.toString(),
        name: dentist.name,
        email: dentist.email,
        phone: dentist.phone_number,
        licenseNumber: profile?.licenseNumber,
        registrationNumber: profile?.registrationNumber,
        clinicName: profile?.clinicName,
        clinicAddress: profile?.clinicAddress
      };
    }
  }

  const invoice = await tx.invoice.create({
    data: {
      appointmentId: appointment?.id ?? null,
      paymentIntentId: paymentIntent.id,
      treatmentPlanId,
      patientId: patient?.id ?? paymentIntent.patientId,
      ownerType: owner.ownerType,
      ownerClinicId: owner.ownerClinicId,
      ownerDentistId: owner.ownerDentistId,
      reference,
      status: 'issued',
      subtotal,
      tax: 0,
      discount: 0,
      total,
      platformFee: split.platformFee,
      clinicShare: split.clinicShare,
      dentistShare: split.dentistShare,
      grandTotal: split.grandTotal,
      currency: paymentIntent.currency || 'IDR',
      issuedAt,
      issuerType,
      issuerName,
      issuerEmail,
      issuerPhone,
      issuerAddress,
      issuerTaxId,
      issuerSnapshot,
      metadata: {
        appointmentId: appointment?.id?.toString?.() ?? null,
        treatmentPlanId: treatmentPlanId?.toString?.() ?? null,
        source: treatmentPlanId ? 'treatment_plan_payment' : 'payment_intent'
      }
    }
  });

  if (lineItems.length) {
    await tx.invoiceLineItem.createMany({
      data: lineItems.map((item) => ({
        invoiceId: invoice.id,
        description: item.description,
        quantity: item.quantity || 1,
        unitPrice: item.unitPrice || 0,
        total: item.total || 0,
        metadata: {}
      }))
    });
  }

  return invoice;
}

export async function recordFinancialEntry({
  tx,
  paymentIntent,
  appointment,
  entryType,
  status,
  direction,
  amount,
  source = 'midtrans',
  metadata = {}
}) {
  if (!tx || !paymentIntent || !entryType || !status || !direction) return null;

  const owner = resolvePaymentOwner(appointment || {});
  const entryAmount = Number.isFinite(amount) ? amount : parseInt(amount || paymentIntent.amount || 0, 10);

  const existing = await tx.financialLedgerEntry.findFirst({
    where: {
      paymentIntentId: paymentIntent.id,
      entryType,
      status,
      direction,
      amount: entryAmount
    }
  });

  if (existing) return existing;

  return tx.financialLedgerEntry.create({
    data: {
      paymentIntentId: paymentIntent.id,
      appointmentId: appointment?.id ?? null,
      ownerType: owner.ownerType,
      ownerClinicId: owner.ownerClinicId,
      ownerDentistId: owner.ownerDentistId,
      entryType,
      status,
      direction,
      amount: entryAmount,
      currency: paymentIntent.currency || 'IDR',
      source,
      metadata
    }
  });
}

import crypto from 'crypto';

const MIDTRANS_SERVER_KEY = process.env.MIDTRANS_SERVER_KEY || '';
const MIDTRANS_CLIENT_KEY = process.env.MIDTRANS_CLIENT_KEY || '';
const MIDTRANS_BASE_URL = process.env.MIDTRANS_BASE_URL || 'https://app.sandbox.midtrans.com';
const MIDTRANS_API_BASE_URL = process.env.MIDTRANS_API_BASE_URL || 'https://api.sandbox.midtrans.com';
const MIDTRANS_MOCK_MODE = (process.env.MIDTRANS_MOCK_MODE || '').toLowerCase() === 'true';

function buildAuthHeader() {
  if (MIDTRANS_MOCK_MODE) {
    return 'Basic mock';
  }
  if (!MIDTRANS_SERVER_KEY) {
    const error = new Error('MIDTRANS_CONFIG_MISSING');
    error.status = 500;
    throw error;
  }
  const token = Buffer.from(`${MIDTRANS_SERVER_KEY}:`).toString('base64');
  return `Basic ${token}`;
}

export function getMidtransClientConfig() {
  if (MIDTRANS_MOCK_MODE) {
    return {
      clientKey: 'mock-client-key',
      baseUrl: 'mock'
    };
  }
  if (!MIDTRANS_CLIENT_KEY) return null;
  return {
    clientKey: MIDTRANS_CLIENT_KEY,
    baseUrl: MIDTRANS_BASE_URL
  };
}

export async function createMidtransTransaction({ paymentIntent, appointment, patient, orderId: overrideOrderId }) {
  if (MIDTRANS_MOCK_MODE) {
    const now = new Date();
    const orderId = overrideOrderId || `appointment-${appointment.id.toString()}-intent-${paymentIntent.id.toString()}`;
    return {
      providerOrderId: orderId,
      providerPaymentId: `mock-${paymentIntent.id.toString()}`,
      redirectUrl: `https://example.com/mock-payment/${paymentIntent.id.toString()}`,
      rawResponse: {
        token: `mock-token-${paymentIntent.id.toString()}`,
        transaction_id: `mock-${paymentIntent.id.toString()}`,
        expiry_time: new Date(now.getTime() + 30 * 60000).toISOString()
      },
      expiresAt: new Date(now.getTime() + 30 * 60000)
    };
  }

  const authHeader = buildAuthHeader();

  const orderId = overrideOrderId || `appointment-${appointment.id.toString()}-intent-${paymentIntent.id.toString()}`;
  const grossAmount = paymentIntent?.amount ?? appointment?.amount ?? 0;

  const payload = {
    transaction_details: {
      order_id: orderId,
      gross_amount: grossAmount
    },
    customer_details: {
      first_name: patient?.name || 'Patient',
      email: patient?.email || undefined,
      phone: patient?.phone_number || undefined
    },
    item_details: [
      {
        id: appointment.id.toString(),
        price: grossAmount,
        quantity: 1,
        name: appointment.reason || 'Dental Appointment'
      }
    ],
    callbacks: {
      finish: process.env.MIDTRANS_FINISH_URL || undefined,
      error: process.env.MIDTRANS_ERROR_URL || undefined,
      pending: process.env.MIDTRANS_PENDING_URL || undefined
    }
  };

  const response = await fetch(`${MIDTRANS_BASE_URL}/snap/v1/transactions`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: authHeader
    },
    body: JSON.stringify(payload)
  });

  if (!response.ok) {
    const errorBody = await response.text();
    const error = new Error(`MIDTRANS_ERROR_${response.status}`);
    error.details = errorBody;
    throw error;
  }

  const data = await response.json();

  return {
    providerOrderId: orderId,
    providerPaymentId: data.token || data.transaction_id || orderId,
    redirectUrl: data.redirect_url || data.payment_url,
    rawResponse: data,
    expiresAt: data.expiry_time ? new Date(data.expiry_time) : null
  };
}

export async function refundMidtransTransaction({ orderId, amount, reason }) {
  if (MIDTRANS_MOCK_MODE) {
    return {
      status: 'mock_refund',
      order_id: orderId,
      amount,
      reason
    };
  }

  const authHeader = buildAuthHeader();
  const payload = {
    refund_key: `refund-${Date.now()}`,
    amount,
    reason
  };

  const response = await fetch(`${MIDTRANS_API_BASE_URL}/v2/${orderId}/refund`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: authHeader
    },
    body: JSON.stringify(payload)
  });

  if (!response.ok) {
    const errorBody = await response.text();
    const error = new Error(`MIDTRANS_REFUND_ERROR_${response.status}`);
    error.details = errorBody;
    throw error;
  }

  return response.json();
}

export async function cancelMidtransTransaction(orderId) {
  if (MIDTRANS_MOCK_MODE) {
    return {
      status: 'mock_cancel',
      order_id: orderId
    };
  }

  const authHeader = buildAuthHeader();
  const response = await fetch(`${MIDTRANS_API_BASE_URL}/v2/${orderId}/cancel`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: authHeader
    }
  });

  if (!response.ok) {
    const errorBody = await response.text();
    const error = new Error(`MIDTRANS_CANCEL_ERROR_${response.status}`);
    error.details = errorBody;
    throw error;
  }

  return response.json();
}

function timingSafeEqualHex(expected, provided) {
  if (!expected || !provided) return false;
  const expectedHex = String(expected).toLowerCase();
  const providedHex = String(provided).toLowerCase();
  if (expectedHex.length !== providedHex.length) return false;
  try {
    const expectedBuffer = Buffer.from(expectedHex, 'hex');
    const providedBuffer = Buffer.from(providedHex, 'hex');
    if (expectedBuffer.length !== providedBuffer.length) return false;
    return crypto.timingSafeEqual(expectedBuffer, providedBuffer);
  } catch (error) {
    return false;
  }
}

export function verifyMidtransSignature({ orderId, statusCode, grossAmount, signatureKey }) {
  if (MIDTRANS_MOCK_MODE) return true;
  if (!MIDTRANS_SERVER_KEY) return false;
  if (!orderId || !statusCode || !grossAmount || !signatureKey) return false;
  const payload = `${orderId}${statusCode}${grossAmount}${MIDTRANS_SERVER_KEY}`;
  const computedSignature = crypto.createHash('sha512').update(payload).digest('hex');
  return timingSafeEqualHex(computedSignature, signatureKey);
}

export function validateMidtransWebhookPayload(body) {
  if (!body || typeof body !== 'object') {
    const error = new Error('MIDTRANS_PAYLOAD_INVALID');
    error.status = 400;
    throw error;
  }

  const orderId = body.order_id;
  const statusCode = body.status_code;
  const grossAmount = body.gross_amount;
  const signatureKey = body.signature_key;
  const transactionStatus = body.transaction_status;
  const transactionId = body.transaction_id || null;

  if (!orderId || !statusCode || !grossAmount || !signatureKey || !transactionStatus) {
    const error = new Error('MIDTRANS_PAYLOAD_MISSING_FIELDS');
    error.status = 400;
    throw error;
  }

  const parsedAmount = Number(grossAmount);
  if (!Number.isFinite(parsedAmount)) {
    const error = new Error('MIDTRANS_GROSS_AMOUNT_INVALID');
    error.status = 400;
    throw error;
  }

  const parsedStatusCode = parseInt(statusCode, 10);
  if (Number.isNaN(parsedStatusCode)) {
    const error = new Error('MIDTRANS_STATUS_CODE_INVALID');
    error.status = 400;
    throw error;
  }

  return {
    orderId: String(orderId),
    statusCode: String(statusCode),
    grossAmount: String(grossAmount),
    grossAmountValue: Math.round(parsedAmount),
    signatureKey: String(signatureKey),
    transactionStatus: String(transactionStatus),
    transactionId: transactionId ? String(transactionId) : null
  };
}

export const FINANCIAL_OWNER_TYPES = Object.freeze({
  CLINIC: 'clinic',
  INDEPENDENT_DENTIST: 'dentist'
});

export const FINANCIAL_OWNER_TYPE_ALIASES = Object.freeze({
  clinic: FINANCIAL_OWNER_TYPES.CLINIC,
  CLINIC: FINANCIAL_OWNER_TYPES.CLINIC,
  independent_dentist: FINANCIAL_OWNER_TYPES.INDEPENDENT_DENTIST,
  INDEPENDENT_DENTIST: FINANCIAL_OWNER_TYPES.INDEPENDENT_DENTIST,
  dentist: FINANCIAL_OWNER_TYPES.INDEPENDENT_DENTIST,
  DENTIST: FINANCIAL_OWNER_TYPES.INDEPENDENT_DENTIST
});

function nullableBigIntLike(value) {
  return value === undefined || value === null || value === '' ? null : value;
}

function ownerIdComparable(value) {
  const normalized = nullableBigIntLike(value);
  return normalized === null ? null : String(normalized);
}

export function normalizeFinancialOwnerType(ownerType) {
  if (ownerType === undefined || ownerType === null || ownerType === '') return null;
  const normalized = FINANCIAL_OWNER_TYPE_ALIASES[String(ownerType)];
  if (!normalized) {
    const error = new Error(`Unsupported financial owner type: ${ownerType}`);
    error.code = 'UNSUPPORTED_FINANCIAL_OWNER_TYPE';
    throw error;
  }
  return normalized;
}

function resolveClinicOwnerId(appointment = {}) {
  return nullableBigIntLike(
    appointment.ownerClinicId ??
    appointment.owner_clinic_id ??
    appointment.clinicBranch?.clinicProfileId ??
    appointment.clinic_branch?.clinic_profile_id ??
    appointment.clinicBranch?.clinic_profile_id
  );
}

function hasClinicAppointmentSignal(appointment = {}) {
  return Boolean(
    nullableBigIntLike(appointment.clinicBranchId ?? appointment.clinic_branch_id) ||
    nullableBigIntLike(appointment.ownerClinicId ?? appointment.owner_clinic_id) ||
    nullableBigIntLike(appointment.clinicBranch?.clinicProfileId ?? appointment.clinic_branch?.clinic_profile_id)
  );
}

export function assertResolvedFinancialOwner(owner) {
  const ownerType = normalizeFinancialOwnerType(owner?.ownerType);
  const ownerClinicId = nullableBigIntLike(owner?.ownerClinicId);
  const ownerDentistId = nullableBigIntLike(owner?.ownerDentistId);

  if (!ownerType) {
    const error = new Error('Financial owner type is required');
    error.code = 'FINANCIAL_OWNER_TYPE_REQUIRED';
    throw error;
  }

  if (ownerType === FINANCIAL_OWNER_TYPES.CLINIC) {
    if (!ownerClinicId || ownerDentistId) {
      const error = new Error('Clinic-owned payments must have exactly one clinic owner and no dentist owner');
      error.code = 'INVALID_CLINIC_FINANCIAL_OWNER';
      throw error;
    }
  }

  if (ownerType === FINANCIAL_OWNER_TYPES.INDEPENDENT_DENTIST) {
    if (!ownerDentistId || ownerClinicId) {
      const error = new Error('Independent dentist-owned payments must have exactly one dentist owner and no clinic owner');
      error.code = 'INVALID_DENTIST_FINANCIAL_OWNER';
      throw error;
    }
  }

  return {
    ownerType,
    ownerClinicId: ownerType === FINANCIAL_OWNER_TYPES.CLINIC ? ownerClinicId : null,
    ownerDentistId: ownerType === FINANCIAL_OWNER_TYPES.INDEPENDENT_DENTIST ? ownerDentistId : null
  };
}

export function assertFinancialOwnershipImmutable(existingOwner, nextData = {}) {
  const ownershipKeys = ['ownerType', 'owner_type', 'ownerClinicId', 'owner_clinic_id', 'ownerDentistId', 'owner_dentist_id'];
  const attemptsOwnershipChange = ownershipKeys.some((key) => Object.prototype.hasOwnProperty.call(nextData || {}, key));
  if (!attemptsOwnershipChange) return true;

  const existing = {
    ownerType: normalizeFinancialOwnerType(existingOwner?.ownerType ?? existingOwner?.owner_type),
    ownerClinicId: ownerIdComparable(existingOwner?.ownerClinicId ?? existingOwner?.owner_clinic_id),
    ownerDentistId: ownerIdComparable(existingOwner?.ownerDentistId ?? existingOwner?.owner_dentist_id)
  };
  const next = {
    ownerType: normalizeFinancialOwnerType(nextData.ownerType ?? nextData.owner_type ?? existing.ownerType),
    ownerClinicId: ownerIdComparable(nextData.ownerClinicId ?? nextData.owner_clinic_id ?? existing.ownerClinicId),
    ownerDentistId: ownerIdComparable(nextData.ownerDentistId ?? nextData.owner_dentist_id ?? existing.ownerDentistId)
  };

  if (
    existing.ownerType !== next.ownerType ||
    existing.ownerClinicId !== next.ownerClinicId ||
    existing.ownerDentistId !== next.ownerDentistId
  ) {
    const error = new Error('Financial ownership is immutable after payment creation');
    error.code = 'FINANCIAL_OWNERSHIP_IMMUTABLE';
    error.status = 409;
    throw error;
  }

  return true;
}

export function resolvePaymentOwner(appointment = {}) {
  const explicitOwnerType = normalizeFinancialOwnerType(appointment.ownerType ?? appointment.owner_type);
  const ownerType = explicitOwnerType || (
    hasClinicAppointmentSignal(appointment)
      ? FINANCIAL_OWNER_TYPES.CLINIC
      : FINANCIAL_OWNER_TYPES.INDEPENDENT_DENTIST
  );

  const ownerClinicId = ownerType === FINANCIAL_OWNER_TYPES.CLINIC
    ? resolveClinicOwnerId(appointment)
    : null;
  const ownerDentistId = ownerType === FINANCIAL_OWNER_TYPES.INDEPENDENT_DENTIST
    ? nullableBigIntLike(appointment.ownerDentistId ?? appointment.owner_dentist_id ?? appointment.dentistId ?? appointment.dentist_id)
    : null;

  return assertResolvedFinancialOwner({
    ownerType,
    ownerClinicId,
    ownerDentistId
  });
}

import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient();

/**
 * Calculate available balance dynamically for clinic dentists or practice owners
 */
export async function getAvailableBalance({ client, ownerType, ownerClinicId, ownerDentistId }) {
  const db = client || prisma;

  const where = ownerType === 'clinic'
    ? { ownerClinicId: BigInt(ownerClinicId) }
    : { ownerDentistId: BigInt(ownerDentistId) };

  const balance = await db.availableBalance.findFirst({ where });
  return balance ? balance.availableAmount : 0;
}

/**
 * Creates and processes a payout batch
 */
export async function createPayoutBatch({ recipientType, items }) {
  return prisma.$transaction(async (tx) => {
    // 1. Calculate total amount
    const totalAmount = items.reduce((sum, item) => sum + item.amount, 0);

    // 2. Validate availability for every item
    for (const item of items) {
      const whereLock = item.recipientType === 'clinic'
        ? { ownerClinicId: BigInt(item.recipientClinicId) }
        : { ownerDentistId: BigInt(item.recipientDentistId) };

      let balanceRecord = await tx.availableBalance.findFirst({
        where: whereLock
      });
      if (!balanceRecord) {
        balanceRecord = await tx.availableBalance.create({
          data: {
            ownerType: item.recipientType,
            ownerClinicId: item.recipientClinicId ? BigInt(item.recipientClinicId) : null,
            ownerDentistId: item.recipientDentistId ? BigInt(item.recipientDentistId) : null,
            availableAmount: 0,
            pendingAmount: 0,
            currency: 'IDR'
          }
        });
      }

      // Concurrency protection: Acquire raw SELECT FOR UPDATE lock
      await tx.$executeRaw`SELECT id FROM available_balances WHERE id = ${balanceRecord.id} FOR UPDATE`;

      const balance = await getAvailableBalance({
        client: tx,
        ownerType: item.recipientType,
        ownerClinicId: item.recipientClinicId,
        ownerDentistId: item.recipientDentistId
      });

      if (item.amount > balance) {
        throw {
          status: 409,
          code: 'OVERPAYMENT_REJECTED',
          message: `Conflict: Payout amount of ${item.amount} IDR exceeds available balance of ${balance} IDR`
        };
      }
    }

    // 3. Create PayoutBatch
    const batch = await tx.payoutBatch.create({
      data: {
        status: 'INITIATED',
        totalAmount
      }
    });

    // 4. Create PayoutItems
    const createdItems = [];
    for (const item of items) {
      const createdItem = await tx.payoutItem.create({
        data: {
          batchId: batch.id,
          recipientType: item.recipientType,
          recipientClinicId: item.recipientClinicId ? BigInt(item.recipientClinicId) : null,
          recipientDentistId: item.recipientDentistId ? BigInt(item.recipientDentistId) : null,
          amount: item.amount,
          status: 'SUCCESS' // simulate successful payout transfer (e.g. mock Iris disbursement)
        }
      });

      // 5. Update available balance record to decrement availableAmount
      const where = item.recipientType === 'clinic'
        ? { ownerClinicId: BigInt(item.recipientClinicId) }
        : { ownerDentistId: BigInt(item.recipientDentistId) };

      await tx.availableBalance.updateMany({
        where,
        data: {
          availableAmount: { decrement: item.amount }
        }
      });

      // 6. Record financial ledger entry for payout
      await tx.financialLedgerEntry.create({
        data: {
          ownerType: item.recipientType,
          ownerClinicId: item.recipientClinicId ? BigInt(item.recipientClinicId) : null,
          ownerDentistId: item.recipientDentistId ? BigInt(item.recipientDentistId) : null,
          entryType: 'PAYOUT',
          status: 'completed',
          direction: 'debit',
          amount: item.amount,
          source: 'system',
          metadata: { payoutItemId: createdItem.id.toString(), payoutBatchId: batch.id.toString() }
        }
      });

      // 7. If recipient is a clinic dentist, record a compensation payout entry
      if (item.recipientType === 'dentist') {
        const profile = await tx.dentistProfile.findFirst({
          where: { userId: BigInt(item.recipientDentistId) }
        });
        if (profile?.dentist_type === 'clinic') {
          await tx.dentistCompensationEntry.create({
            data: {
              dentistId: BigInt(item.recipientDentistId),
              clinicId: profile.clinic_id,
              entryType: 'PAYOUT',
              amount: item.amount,
              status: 'paid',
              metadata: { payoutItemId: createdItem.id.toString() }
            }
          });

          await tx.financialLedgerEntry.create({
            data: {
              ownerType: 'dentist',
              ownerDentistId: BigInt(item.recipientDentistId),
              entryType: 'COMMISSION_PAID',
              status: 'completed',
              direction: 'debit',
              amount: item.amount,
              source: 'system',
              metadata: { payoutItemId: createdItem.id.toString() }
            }
          });
        }
      }

      createdItems.push(createdItem);
    }

    // Complete the batch
    const completedBatch = await tx.payoutBatch.update({
      where: { id: batch.id },
      data: { status: 'COMPLETED', completedAt: new Date() },
      include: { items: true }
    });

    return completedBatch;
  });
}

import PDFDocument from 'pdfkit';
import { FINANCIAL_OWNER_TYPES, normalizeFinancialOwnerType } from './ownership.js';

/**
 * Draw a clean, print-friendly PDF invoice to the output stream.
 */
export function generateInvoicePDF(invoice, stream) {
  const doc = new PDFDocument({ margin: 50, size: 'A4' });
  doc.pipe(stream);

  // Core color theme
  const primaryColor = '#0EA5E9'; // Clean sky blue
  const textColor = '#1E293B'; // Dark Slate
  const lightText = '#64748B'; // Muted Slate
  const border = '#E2E8F0'; // Light Slate border

  // 1. Header (Brand and invoice reference)
  doc.fillColor(primaryColor).fontSize(20).font('Helvetica-Bold').text('SERENE APPS', 50, 50);
  doc.fillColor(lightText).fontSize(9).font('Helvetica').text('Premium Dental Care & Teledentistry Platform', 50, 72);

  doc.fillColor(textColor).fontSize(16).font('Helvetica-Bold').text('OFFICIAL INVOICE', 350, 50, { align: 'right' });
  doc.fillColor(lightText).fontSize(10).font('Helvetica').text(`Invoice Ref: ${invoice.reference || 'INV-' + invoice.id}`, 350, 72, { align: 'right' });

  // Border separator
  doc.moveTo(50, 95).lineTo(545, 95).strokeColor(border).stroke();

  // 2. Billing details (Patient vs Provider grid)
  let y = 115;
  doc.fillColor(primaryColor).fontSize(11).font('Helvetica-Bold').text('PATIENT INFO', 50, y);
  doc.fillColor(textColor).fontSize(10).font('Helvetica').text(`Name: ${invoice.patient?.name || 'N/A'}`, 50, y + 20);
  doc.text(`Email: ${invoice.patient?.email || 'N/A'}`, 50, y + 35);
  doc.text(`Phone: ${invoice.patient?.phone_number || 'N/A'}`, 50, y + 50);

  doc.fillColor(primaryColor).fontSize(11).font('Helvetica-Bold').text('PROVIDER INFO', 320, y);
  doc.fillColor(textColor).fontSize(10).font('Helvetica');
  if (normalizeFinancialOwnerType(invoice.ownerType) === FINANCIAL_OWNER_TYPES.CLINIC && invoice.ownerClinic) {
    doc.text(`Clinic: ${invoice.ownerClinic.legalName}`, 320, y + 20);
    doc.text(`Email: ${invoice.ownerClinic.email || 'N/A'}`, 320, y + 35);
    doc.text(`Phone: ${invoice.ownerClinic.phone || 'N/A'}`, 320, y + 50);
  } else {
    doc.text(`Dentist: drg. ${invoice.appointment?.dentist?.name || 'Dentist'}`, 320, y + 20);
    doc.text(`Email: ${invoice.appointment?.dentist?.email || 'N/A'}`, 320, y + 35);
  }

  // Border separator
  doc.moveTo(50, 195).lineTo(545, 195).strokeColor(border).stroke();

  // 3. Invoice meta status
  y = 210;
  doc.fillColor(lightText).fontSize(9).text('Issued Date:', 50, y);
  doc.fillColor(textColor).fontSize(9).font('Helvetica-Bold').text(invoice.issuedAt ? new Date(invoice.issuedAt).toLocaleDateString('id-ID', { dateStyle: 'long' }) : 'N/A', 115, y);

  doc.fillColor(lightText).font('Helvetica').text('Due Date:', 50, y + 15);
  doc.fillColor(textColor).font('Helvetica-Bold').text(invoice.dueAt ? new Date(invoice.dueAt).toLocaleDateString('id-ID', { dateStyle: 'long' }) : 'N/A', 115, y + 15);

  const status = (invoice.paymentIntent?.status || 'pending').toUpperCase();
  doc.fillColor(lightText).font('Helvetica').text('Payment Status:', 320, y);
  doc.fillColor(status === 'SETTLED' || status === 'PAID' ? '#10B981' : '#F59E0B').font('Helvetica-Bold').text(status, 410, y);

  doc.fillColor(lightText).font('Helvetica').text('Channel Method:', 320, y + 15);
  const paymentMethodStr = invoice.paymentSnapshot?.paymentMethod || invoice.paymentIntent?.providerResponse?.payment_type || 'Online Transfer';
  doc.fillColor(textColor).font('Helvetica-Bold').text(String(paymentMethodStr).toUpperCase(), 410, y + 15);

  // Border separator
  doc.moveTo(50, 245).lineTo(545, 245).strokeColor(border).stroke();

  // 4. Line Items Table
  y = 265;
  doc.fillColor(primaryColor).fontSize(10).font('Helvetica-Bold').text('Item Description', 50, y);
  doc.text('Qty', 320, y, { align: 'right' });
  doc.text('Unit Price', 410, y, { align: 'right' });
  doc.text('Total', 500, y, { align: 'right' });

  doc.moveTo(50, 280).lineTo(545, 280).strokeColor(border).stroke();

  let currentY = 295;
  const lineItems = invoice.items || [];
  doc.fillColor(textColor).fontSize(9).font('Helvetica');

  if (lineItems.length === 0) {
    doc.text('Dental Consultation Service', 50, currentY);
    doc.text('1', 320, currentY, { align: 'right' });
    doc.text(`${Number(invoice.total).toLocaleString('id-ID')} IDR`, 410, currentY, { align: 'right' });
    doc.text(`${Number(invoice.total).toLocaleString('id-ID')} IDR`, 500, currentY, { align: 'right' });
    currentY += 20;
  } else {
    for (const item of lineItems) {
      doc.text(item.description, 50, currentY);
      doc.text(String(item.quantity), 320, currentY, { align: 'right' });
      doc.text(`${Number(item.unitPrice).toLocaleString('id-ID')} IDR`, 410, currentY, { align: 'right' });
      doc.text(`${Number(item.total).toLocaleString('id-ID')} IDR`, 500, currentY, { align: 'right' });
      currentY += 20;
    }
  }

  doc.moveTo(50, currentY).lineTo(545, currentY).strokeColor(border).stroke();
  currentY += 15;

  // 5. Total Calculations summary
  doc.fillColor(lightText).font('Helvetica').text('Subtotal:', 350, currentY, { align: 'right' });
  doc.fillColor(textColor).font('Helvetica-Bold').text(`${Number(invoice.subtotal).toLocaleString('id-ID')} IDR`, 500, currentY, { align: 'right' });
  currentY += 15;

  if (invoice.discount > 0) {
    doc.fillColor(lightText).font('Helvetica').text('Discount:', 350, currentY, { align: 'right' });
    doc.fillColor('#EF4444').font('Helvetica-Bold').text(`-${Number(invoice.discount).toLocaleString('id-ID')} IDR`, 500, currentY, { align: 'right' });
    currentY += 15;
  }

  if (invoice.tax > 0) {
    doc.fillColor(lightText).font('Helvetica').text('Tax:', 350, currentY, { align: 'right' });
    doc.fillColor(textColor).font('Helvetica-Bold').text(`${Number(invoice.tax).toLocaleString('id-ID')} IDR`, 500, currentY, { align: 'right' });
    currentY += 15;
  }

  doc.fillColor(primaryColor).font('Helvetica-Bold').text('Total Paid Amount:', 350, currentY, { align: 'right' });
  doc.text(`${Number(invoice.total).toLocaleString('id-ID')} IDR`, 500, currentY, { align: 'right' });
  currentY += 45;

  // 6. Signature / QR code verification block
  doc.moveTo(50, currentY).lineTo(545, currentY).strokeColor(border).stroke();
  currentY += 15;

  doc.fillColor(textColor).fontSize(8).font('Helvetica-Bold').text('DIGITAL VERIFICATION STATEMENT', 50, currentY);
  doc.fillColor(lightText).font('Helvetica').text('This invoice was generated electronically and is certified by SereneApps. Scan the secure seal below to check database integrity.', 50, currentY + 12, { width: 280 });

  // Draw verified badge QR look-alike
  doc.strokeColor(primaryColor).rect(380, currentY, 65, 65).stroke();
  doc.fillColor(primaryColor).fontSize(6).font('Helvetica-Bold').text('VERIFIED', 382, currentY + 10, { width: 61, align: 'center' });
  doc.fillColor(textColor).fontSize(4).text('ORDER ID: ' + (invoice.paymentIntent?.providerOrderId || 'N/A'), 382, currentY + 22, { width: 61, align: 'center' });
  doc.text('INTENT ID: ' + (invoice.paymentIntentId?.toString() || 'N/A'), 382, currentY + 32, { width: 61, align: 'center' });

  // Closing greeting
  doc.fillColor(lightText).fontSize(8).font('Helvetica-Oblique').text('Wishing you good health and bright smiles!', 50, currentY + 52);

  doc.end();
}

import { PrismaClient } from '@prisma/client';
import midtransService from './midtransService.js';
import { mapMidtransStatus } from './statusMapping.js';
import { PAYMENT_STATUSES, canTransition } from './status.js';
import { applyPaymentStatus } from './status.js';

const prisma = new PrismaClient();

export async function reconcilePayment(paymentIntentId) {
  const intentIdBigInt = typeof paymentIntentId === 'bigint' ? paymentIntentId : BigInt(paymentIntentId);

  // 1. Load payment_intents by id
  const paymentIntent = await prisma.paymentIntent.findUnique({
    where: { id: intentIdBigInt }
  });

  if (!paymentIntent) {
    throw { code: 'PAYMENT_INTENT_NOT_FOUND', message: 'Payment intent not found.' };
  }

  const previousStatus = paymentIntent.status;
  await prisma.paymentIntent.update({
    where: { id: intentIdBigInt },
    data: {
      reconciliationStatus: 'reconciling',
      reconciliationAttempts: { increment: 1 },
      reconciliationError: null,
      lastReconciledAt: new Date()
    }
  });

  // 2. Already final
  if ([PAYMENT_STATUSES.SETTLED, PAYMENT_STATUSES.FAILED, PAYMENT_STATUSES.REFUNDED, PAYMENT_STATUSES.PARTIAL_REFUND, PAYMENT_STATUSES.CANCELLED, PAYMENT_STATUSES.EXPIRED].includes(previousStatus)) {
    await prisma.paymentIntent.update({
      where: { id: intentIdBigInt },
      data: { reconciliationStatus: 'finalized', lastReconciledAt: new Date() }
    });
    return { alreadyFinal: true, previousStatus, newStatus: previousStatus };
  }

  // 3. Status check from Midtrans directly
  let midtransStatus;
  try {
    midtransStatus = await midtransService.getTransactionStatus(paymentIntent.providerOrderId);
  } catch (err) {
    if (err?.statusCode === 404 && canTransition(previousStatus, PAYMENT_STATUSES.EXPIRED)) {
      await applyPaymentStatus({
        paymentIntentId: intentIdBigInt,
        newStatus: PAYMENT_STATUSES.EXPIRED,
        providerResponse: { error: err.message || 'MIDTRANS_ORDER_NOT_FOUND' },
        failureReason: 'provider_not_found'
      });
      await prisma.paymentIntent.update({
        where: { id: intentIdBigInt },
        data: { reconciliationStatus: 'reconciled', reconciliationError: null, lastReconciledAt: new Date() }
      });
      return { reconciled: true, previousStatus, newStatus: PAYMENT_STATUSES.EXPIRED };
    }
    await prisma.paymentIntent.update({
      where: { id: intentIdBigInt },
      data: {
        reconciliationStatus: 'failed',
        reconciliationError: err?.message?.slice?.(0, 255) || 'MIDTRANS_STATUS_ERROR'
      }
    });
    throw err;
  }

  // 4. Map Midtrans response identically handling identical webhooks logic
  const { internalStatus: mappedStatus, failureReason } = mapMidtransStatus({
    transactionStatus: midtransStatus.transaction_status,
    fraudStatus: midtransStatus.fraud_status
  });

  if (!canTransition(previousStatus, mappedStatus) && previousStatus !== mappedStatus) {
    await prisma.paymentIntent.update({
      where: { id: intentIdBigInt },
      data: {
        reconciliationStatus: 'skipped',
        reconciliationError: 'RECONCILE_TRANSITION_INVALID'
      }
    });
    return { reconciled: false, previousStatus, newStatus: previousStatus };
  }

  if (mappedStatus !== previousStatus) {
    await applyPaymentStatus({
      paymentIntentId: intentIdBigInt,
      newStatus: mappedStatus,
      providerPaymentId: midtransStatus.transaction_id || paymentIntent.providerPaymentId,
      providerResponse: midtransStatus,
      failureReason
    });
  }

  await prisma.paymentIntent.update({
    where: { id: intentIdBigInt },
    data: { reconciliationStatus: 'reconciled', lastReconciledAt: new Date(), reconciliationError: null }
  });

  console.log('[ReconcileJob]', {
    paymentIntentId: String(paymentIntentId),
    previousStatus,
    newStatus: mappedStatus,
    provider_order_id: paymentIntent.providerOrderId
  });

  return { reconciled: true, previousStatus, newStatus: mappedStatus };
}

export async function runReconcileBatch() {
  const fiveMinAgo = new Date(Date.now() - 5 * 60 * 1000);
  const thirtyMinAgo = new Date(Date.now() - 30 * 60 * 1000);

  const intents = await prisma.paymentIntent.findMany({
    where: {
      status: { in: ['pending', 'requires_action', 'paid'] },
      createdAt: { lt: fiveMinAgo },
      OR: [
        { lastReconciledAt: null },
        { lastReconciledAt: { lt: thirtyMinAgo } }
      ],
      reconciliationAttempts: { lt: 8 }
    },
    take: 20
  });

  const errors = [];
  let processed = 0;

  for (const intent of intents) {
    try {
       await reconcilePayment(intent.id);
       processed++;
    } catch (err) {
       console.warn(`[ReconcileBatch] Failed reconciling intent ${intent.id}:`, err.message);
       errors.push({ id: String(intent.id), error: err.message });
    }
  }

  return { processed, errors };
}

export function startReconcileScheduler() {
  console.log('[ReconcileScheduler] Synchronous loop initialized.');
  return setInterval(runReconcileBatch, 15 * 60 * 1000);
}

import { PrismaClient } from '@prisma/client';
import { refundMidtransTransaction } from './midtrans.js';
import { recordFinancialAuditLog } from '../audit/auditLogger.js';
import { FINANCIAL_OWNER_TYPES, normalizeFinancialOwnerType } from './ownership.js';
import { assertPeriodNotLocked } from './periodLockService.js';

const prisma = new PrismaClient();

/**
 * Execute a refund for a payment intent.
 */
export async function processRefund({
  paymentIntentId,
  refundAmount,
  refundReason,
  actorId,
  actorRoles = [],
  ipAddress = null
}) {
  const intentIdBigInt = BigInt(paymentIntentId);

  // 1. Fetch payment intent with appointment and owner
  const paymentIntent = await prisma.paymentIntent.findUnique({
    where: { id: intentIdBigInt },
    include: { appointment: true }
  });

  if (!paymentIntent) {
    throw { code: 'NOT_FOUND', message: 'Payment intent not found', status: 404 };
  }

  // Assert period not locked before refund
  await assertPeriodNotLocked(paymentIntent.createdAt);

  if (!['paid', 'settled'].includes(paymentIntent.status)) {
    throw { code: 'BAD_REQUEST', message: 'Only paid or settled payments can be refunded', status: 400 };
  }

  // 2. Role-based access validation
  const userId = BigInt(actorId);
  let isAuthorized = actorRoles.includes('admin') || actorRoles.includes('super_admin');

  if (!isAuthorized) {
    const ownerType = normalizeFinancialOwnerType(paymentIntent.ownerType);
    if (ownerType === FINANCIAL_OWNER_TYPES.CLINIC && paymentIntent.ownerClinicId) {
      // Check if user is staff/owner of this clinic
      const staffRecord = await prisma.clinicStaff.findFirst({
        where: {
          userId,
          clinicProfileId: paymentIntent.ownerClinicId,
          isActive: true
        }
      });
      const clinicOwner = await prisma.clinicProfile.findFirst({
        where: {
          id: paymentIntent.ownerClinicId,
          userId
        }
      });
      if (staffRecord || clinicOwner) {
        isAuthorized = true;
      }
    } else if (ownerType === FINANCIAL_OWNER_TYPES.INDEPENDENT_DENTIST && paymentIntent.ownerDentistId) {
      // Check if independent dentist owns this payment intent
      if (paymentIntent.ownerDentistId === userId) {
        isAuthorized = true;
      }
    }
  }

  if (!isAuthorized) {
    throw { code: 'FORBIDDEN', message: 'You are not authorized to perform refunds for this transaction', status: 403 };
  }

  // Calculate previously refunded amount
  const previousRefunds = await prisma.refund.findMany({
    where: {
      paymentIntentId: intentIdBigInt,
      refundStatus: { in: ['processed', 'refunded'] }
    }
  });
  const totalPreviouslyRefunded = previousRefunds.reduce((sum, r) => sum + r.refundAmount, 0);
  const remainingRefundableAmount = paymentIntent.amount - totalPreviouslyRefunded;

  if (refundAmount > remainingRefundableAmount) {
    throw { code: 'BAD_REQUEST', message: `Requested refund amount exceeds remaining refundable amount (${remainingRefundableAmount} IDR)`, status: 400 };
  }

  // 3. Trigger Midtrans Refund
  let providerRefundResult = null;
  let refundStatus = 'pending';
  let providerRefundReference = null;

  try {
    providerRefundResult = await refundMidtransTransaction({
      orderId: paymentIntent.providerOrderId,
      amount: refundAmount,
      reason: refundReason
    });

    refundStatus = 'processed';
    providerRefundReference = providerRefundResult.refund_id || providerRefundResult.providerRefundReference || `mock-ref-${Date.now()}`;
  } catch (error) {
    console.error('[RefundService] Midtrans API Refund request failed:', error);
    refundStatus = 'failed';

    await recordFinancialAuditLog({
      actorId,
      actorRole: actorRoles[0] || 'anonymous',
      entityType: 'payment_intent',
      entityId: paymentIntentId.toString(),
      action: 'refund_rejected',
      metadata: {
        amount: refundAmount,
        reason: refundReason,
        error: error.message || error
      }
    });

    throw { code: 'PROVIDER_ERROR', message: `Provider refund rejected: ${error.message || error}`, status: 502 };
  }

  // 4. Save to Database (Prisma Transaction)
  const result = await prisma.$transaction(async (tx) => {
    // Create refund record
    const refund = await tx.refund.create({
      data: {
        paymentIntentId: intentIdBigInt,
        refundAmount,
        refundReason,
        refundStatus,
        refundActorId: userId,
        providerRefundReference,
        internalNotes: 'Automated Midtrans Snap refund request'
      }
    });

    // Update payment intent status
    const isFullRefund = (totalPreviouslyRefunded + refundAmount) >= paymentIntent.amount;
    const newStatus = isFullRefund ? 'refunded' : 'partial_refund';

    await tx.paymentIntent.update({
      where: { id: intentIdBigInt },
      data: { status: newStatus, activeAppointmentId: null }
    });

    // Update invoice status
    const invoice = await tx.invoice.findFirst({
      where: { paymentIntentId: intentIdBigInt }
    });
    if (invoice) {
      await tx.invoice.update({
        where: { id: invoice.id },
        data: { status: newStatus }
      });
    }

    // Write internal ledger debit entries
    await tx.paymentLedger.create({
      data: {
        paymentIntentId: intentIdBigInt,
        entryType: 'refund',
        status: newStatus,
        amount: refundAmount,
        metadata: { refundId: refund.id.toString(), providerRefundResult }
      }
    });

    // Write financial ledger entry
    await tx.financialLedgerEntry.create({
      data: {
        paymentIntentId: intentIdBigInt,
        appointmentId: paymentIntent.appointmentId,
        ownerType: paymentIntent.ownerType,
        ownerClinicId: paymentIntent.ownerClinicId,
        ownerDentistId: paymentIntent.ownerDentistId,
        entryType: isFullRefund ? 'REFUND' : 'PARTIAL_REFUND',
        status: newStatus,
        direction: 'debit',
        amount: refundAmount,
        currency: paymentIntent.currency || 'IDR',
        source: 'midtrans',
        metadata: { refundId: refund.id.toString() }
      }
    });

    // 1. Update available balance record to decrement availableAmount
    const whereBalance = paymentIntent.ownerType === 'clinic'
      ? { ownerClinicId: paymentIntent.ownerClinicId }
      : { ownerDentistId: paymentIntent.ownerDentistId };

    const balance = await tx.availableBalance.findFirst({ where: whereBalance });
    const isNegative = balance ? (balance.availableAmount - refundAmount < 0) : true;

    if (balance) {
      await tx.availableBalance.update({
        where: { id: balance.id },
        data: {
          availableAmount: { decrement: refundAmount }
        }
      });
    } else {
      await tx.availableBalance.create({
        data: {
          ownerType: paymentIntent.ownerType,
          ownerClinicId: paymentIntent.ownerClinicId,
          ownerDentistId: paymentIntent.ownerDentistId,
          availableAmount: -refundAmount,
          pendingAmount: 0,
          currency: paymentIntent.currency || 'IDR'
        }
      });
    }

    // Write a DEBT ledger entry if the balance went negative
    if (isNegative) {
      const currentAvailable = balance ? balance.availableAmount : 0;
      const debtAmount = Math.abs(currentAvailable - refundAmount);
      await tx.financialLedgerEntry.create({
        data: {
          paymentIntentId: intentIdBigInt,
          appointmentId: paymentIntent.appointmentId,
          ownerType: paymentIntent.ownerType,
          ownerClinicId: paymentIntent.ownerClinicId,
          ownerDentistId: paymentIntent.ownerDentistId,
          entryType: 'DEBT',
          status: 'completed',
          direction: 'debit',
          amount: debtAmount,
          source: 'system',
          metadata: { refundId: refund.id.toString(), note: 'Available balance went negative after refund' }
        }
      });
    }

    // 2. If clinic dentist appointment, reverse compensation (30% of refundAmount)
    if (paymentIntent.ownerType === 'clinic' && paymentIntent.appointmentId) {
      const appRecord = await tx.appointment.findUnique({
        where: { id: paymentIntent.appointmentId }
      });
      if (appRecord?.dentistId) {
        const profile = await tx.dentistProfile.findFirst({
          where: { userId: appRecord.dentistId }
        });
        if (profile?.dentist_type === 'clinic') {
          const reversedCompensation = Math.round(refundAmount * 0.3);

          await tx.dentistCompensationEntry.create({
            data: {
              appointmentId: paymentIntent.appointmentId,
              paymentIntentId: paymentIntent.id,
              dentistId: appRecord.dentistId,
              clinicId: paymentIntent.ownerClinicId,
              entryType: 'REVERSAL',
              amount: reversedCompensation,
              status: 'paid',
              metadata: { refundId: refund.id.toString() }
            }
          });

          await tx.financialLedgerEntry.create({
            data: {
              paymentIntentId: paymentIntent.id,
              appointmentId: paymentIntent.appointmentId,
              ownerType: 'dentist',
              ownerDentistId: appRecord.dentistId,
              entryType: 'REVERSAL',
              status: 'completed',
              direction: 'debit',
              amount: reversedCompensation,
              source: 'system',
              metadata: { refundId: refund.id.toString() }
            }
          });

          // Decrement the dentist's available balance
          const dentistBalance = await tx.availableBalance.findFirst({
            where: { ownerDentistId: appRecord.dentistId }
          });
          if (dentistBalance) {
            await tx.availableBalance.update({
              where: { id: dentistBalance.id },
              data: {
                availableAmount: { decrement: reversedCompensation }
              }
            });
          } else {
            await tx.availableBalance.create({
              data: {
                ownerType: 'dentist',
                ownerDentistId: appRecord.dentistId,
                availableAmount: -reversedCompensation,
                pendingAmount: 0,
                currency: paymentIntent.currency || 'IDR'
              }
            });
          }
        }
      }
    }

    return refund;
  });

  // 5. Write Financial Audit Log
  await recordFinancialAuditLog({
    actorId,
    actorRole: actorRoles[0] || 'anonymous',
    entityType: 'refund',
    entityId: result.id.toString(),
    action: 'refund_approved',
    metadata: {
      paymentIntentId: paymentIntentId.toString(),
      refundAmount,
      refundReason,
      refundStatus,
      providerRefundReference
    }
  });

  return result;
}

import { PrismaClient } from '@prisma/client';
import { ensureCommunicationResourcesForAppointment, emitAppointmentEvent } from '../communications.js';
import { queueNotificationEvent } from '../notifications/index.js';
import { recordLedgerEntryIfMissing } from './ledger.js';
import { recordFinancialEntry, ensureInvoiceForPaymentIntent } from './financials.js';
import { createPaymentSnapshot } from './snapshotService.js';
import { createSettlement } from './settlementService.js';
import { accrueCompensation } from './compensationService.js';
import { emitToUserRooms } from '../../sockets/chat.js';

const prisma = new PrismaClient();

export const PAYMENT_STATUSES = Object.freeze({
  PENDING: 'pending',
  REQUIRES_ACTION: 'requires_action',
  PAID: 'paid',
  SETTLED: 'settled',
  FAILED: 'failed',
  EXPIRED: 'expired',
  CANCELLED: 'cancelled',
  REFUNDED: 'refunded',
  PARTIAL_REFUND: 'partial_refund'
});

export const VALID_PAYMENT_STATUSES = Object.values(PAYMENT_STATUSES);

export const ACTIVE_PAYMENT_STATUSES = new Set([
  PAYMENT_STATUSES.PENDING,
  PAYMENT_STATUSES.REQUIRES_ACTION,
  PAYMENT_STATUSES.PAID
]);

export function resolveActiveAppointmentId(status, appointmentId) {
  if (!appointmentId) return null;
  return ACTIVE_PAYMENT_STATUSES.has(status) ? appointmentId : null;
}

function parsePositiveAmount(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed > 0 ? Math.round(parsed) : null;
}

export function resolveRefundAmount(providerResponse = {}, paymentAmount = 0) {
  const paymentTotal = parsePositiveAmount(paymentAmount) || 0;
  const directAmount = parsePositiveAmount(providerResponse.refund_amount ?? providerResponse.refundAmount);
  if (directAmount) return Math.min(directAmount, paymentTotal);

  if (Array.isArray(providerResponse.refund_amounts)) {
    const summed = providerResponse.refund_amounts.reduce((sum, item) => {
      return sum + (parsePositiveAmount(item?.amount ?? item?.refund_amount ?? item?.refundAmount) || 0);
    }, 0);
    if (summed > 0) return Math.min(summed, paymentTotal);
  }

  return paymentTotal;
}

const appointmentSelect = {
  id: true,
  dentistId: true,
  patientId: true,
  status: true,
  chatRoomRef: true,
  videoRoomRef: true,
  commStatus: true,
  ownerType: true,
  ownerClinicId: true
};

function mapStatusToAppointment(status) {
  switch (status) {
    case PAYMENT_STATUSES.PAID:
    case PAYMENT_STATUSES.SETTLED:
      return 'confirmed';
    case PAYMENT_STATUSES.FAILED:
    case PAYMENT_STATUSES.EXPIRED:
      return 'payment_failed';
    case PAYMENT_STATUSES.CANCELLED:
      return 'cancelled';
    default:
      return null;
  }
}

function mapStatusToEvent(status) {
  switch (status) {
    case PAYMENT_STATUSES.PAID:
    case PAYMENT_STATUSES.SETTLED:
      return 'appointment_confirmed';
    case PAYMENT_STATUSES.FAILED:
    case PAYMENT_STATUSES.EXPIRED:
      return 'appointment_payment_failed';
    case PAYMENT_STATUSES.CANCELLED:
      return 'appointment_cancelled';
    default:
      return 'payment_status_updated';
  }
}

async function syncCommunications(appointment, status) {
  if (!appointment) return null;
  const appointmentId = appointment.id;

  if (status === 'confirmed') {
    const resources = await ensureCommunicationResourcesForAppointment({
      appointmentId,
      reason: 'payment_status_sync'
    });

    await queueNotificationEvent({
      eventType: 'chat_invite',
      appointmentId,
      payload: {
        roomName: resources.roomName,
        conversationSid: resources.conversationSid
      }
    }).catch((error) => {
      console.error('Chat invite notification error:', error);
    });

    return { chatRoomRef: resources.chatRoom.channelName, videoRoomRef: resources.roomName };
  }

  if (['payment_failed', 'cancelled'].includes(status)) {
    await prisma.appointment.update({
      where: { id: appointmentId },
      data: { commStatus: 'cancelled' }
    }).catch(() => null);
  }

  return null;
}

export function canTransition(fromStatus, toStatus) {
  if (fromStatus === toStatus) return true;
  const allowed = {
    [PAYMENT_STATUSES.PENDING]: [
      PAYMENT_STATUSES.REQUIRES_ACTION,
      PAYMENT_STATUSES.PAID,
      PAYMENT_STATUSES.SETTLED,
      PAYMENT_STATUSES.FAILED,
      PAYMENT_STATUSES.EXPIRED,
      PAYMENT_STATUSES.CANCELLED
    ],
    [PAYMENT_STATUSES.REQUIRES_ACTION]: [
      PAYMENT_STATUSES.PAID,
      PAYMENT_STATUSES.SETTLED,
      PAYMENT_STATUSES.FAILED,
      PAYMENT_STATUSES.EXPIRED,
      PAYMENT_STATUSES.CANCELLED
    ],
    [PAYMENT_STATUSES.PAID]: [
      PAYMENT_STATUSES.SETTLED,
      PAYMENT_STATUSES.REFUNDED,
      PAYMENT_STATUSES.PARTIAL_REFUND
    ],
    [PAYMENT_STATUSES.SETTLED]: [
      PAYMENT_STATUSES.REFUNDED,
      PAYMENT_STATUSES.PARTIAL_REFUND
    ],
    [PAYMENT_STATUSES.PARTIAL_REFUND]: [
      PAYMENT_STATUSES.REFUNDED
    ]
  };

  const nextStatuses = allowed[fromStatus] || [];
  return nextStatuses.includes(toStatus);
}

export async function applyPaymentStatus({
  paymentIntentId,
  newStatus,
  providerPaymentId,
  providerResponse,
  failureReason,
  tx: externalTx
}) {
  if (!VALID_PAYMENT_STATUSES.includes(newStatus)) {
    const error = new Error(`Invalid status: ${newStatus}`);
    error.status = 400;
    throw error;
  }

  const runUpdates = async (tx) => {
    const intent = await tx.paymentIntent.findUnique({
      where: { id: BigInt(paymentIntentId) },
      include: {
        appointment: { select: appointmentSelect },
        patient: { select: { id: true, name: true, email: true, phone_number: true } }
      }
    });

    if (!intent) {
      const error = new Error('PAYMENT_INTENT_NOT_FOUND');
      error.status = 404;
      throw error;
    }

    if (intent.status === newStatus) {
      return {
        paymentIntent: intent,
        appointmentStatus: mapStatusToAppointment(newStatus),
        appointment: intent.appointment,
        noOp: true
      };
    }

    if (!canTransition(intent.status, newStatus)) {
      const error = new Error('PAYMENT_STATUS_TRANSITION_INVALID');
      error.status = 400;
      throw error;
    }

    const mergedProviderResponse = {
      ...(intent.providerResponse || {}),
      ...(providerResponse || {})
    };
    if (failureReason) {
      mergedProviderResponse.failureReason = failureReason;
    }

    // Check accounting period lock
    // For webhook-driven updates, if the period is locked, we want to allow updating the intent status, 
    // but we ensure all new financial transactions are dated today (active period).
    const periodKey = intent.createdAt.toISOString().slice(0, 7);
    const lockedPeriod = await tx.accountingPeriod.findUnique({
      where: { periodKey }
    });
    const isLocked = !!lockedPeriod?.isLocked;

    // If it's a manual transition (no externalTx) and locked, reject
    if (isLocked && !externalTx) {
      throw {
        status: 400,
        code: 'PERIOD_LOCKED',
        message: `Operation rejected: The accounting period for ${periodKey} is locked.`
      };
    }

    const updatedIntent = await tx.paymentIntent.update({
      where: { id: intent.id },
      data: {
        status: newStatus,
        providerPaymentId: providerPaymentId || intent.providerPaymentId,
        providerResponse: mergedProviderResponse,
        metadata: failureReason
          ? { ...(intent.metadata || {}), failureReason }
          : intent.metadata,
        activeAppointmentId: resolveActiveAppointmentId(newStatus, intent.appointmentId)
      },
      include: {
        appointment: { select: appointmentSelect },
        patient: { select: { id: true, name: true, email: true, phone_number: true } }
      }
    });

    const appointmentStatus = mapStatusToAppointment(newStatus);
    let appointment = updatedIntent.appointment;

    if (appointmentStatus) {
      appointment = await tx.appointment.update({
        where: { id: appointment.id },
        data: { status: appointmentStatus },
        select: appointmentSelect
      });
    }

    if ([PAYMENT_STATUSES.PAID, PAYMENT_STATUSES.SETTLED].includes(newStatus)) {
      const entryType = newStatus === PAYMENT_STATUSES.SETTLED ? 'SETTLEMENT_COMPLETED' : 'PAYMENT_RECEIVED';

      await recordLedgerEntryIfMissing({
        paymentIntentId: intent.id,
        entryType: newStatus === PAYMENT_STATUSES.SETTLED ? 'settlement' : 'charge',
        status: newStatus,
        amount: updatedIntent.amount,
        metadata: mergedProviderResponse
      }, tx);

      await recordFinancialEntry({
        tx,
        paymentIntent: updatedIntent,
        appointment: updatedIntent.appointment,
        entryType,
        status: newStatus,
        direction: 'credit',
        amount: updatedIntent.amount,
        source: updatedIntent.provider || 'midtrans',
        metadata: mergedProviderResponse
      });

      const invoice = await ensureInvoiceForPaymentIntent({
        tx,
        paymentIntent: updatedIntent,
        appointment: updatedIntent.appointment,
        patient: updatedIntent.patient
      });

      if (invoice?.id) {
        await tx.invoice.update({
          where: { id: invoice.id },
          data: {
            status: newStatus === PAYMENT_STATUSES.SETTLED ? 'settled' : 'paid',
            paidAt: invoice.paidAt || new Date()
          }
        }).catch(() => null);
      }

      if (newStatus === PAYMENT_STATUSES.SETTLED) {
        const snapshot = await createPaymentSnapshot({
          tx,
          paymentIntent: updatedIntent,
          invoice,
          appointment: updatedIntent.appointment
        });

        await createSettlement({
          tx,
          paymentIntent: updatedIntent,
          providerReference: updatedIntent.providerPaymentId
        });

        await accrueCompensation({
          tx,
          paymentIntent: updatedIntent,
          snapshot,
          appointment: updatedIntent.appointment
        });
      }
    }

    if ([PAYMENT_STATUSES.REFUNDED, PAYMENT_STATUSES.PARTIAL_REFUND].includes(newStatus)) {
      const refundAmount = resolveRefundAmount(mergedProviderResponse, updatedIntent.amount);
      const entryType = newStatus === PAYMENT_STATUSES.PARTIAL_REFUND ? 'PARTIAL_REFUND' : 'REFUND';

      await recordLedgerEntryIfMissing({
        paymentIntentId: intent.id,
        entryType: 'refund',
        status: newStatus,
        amount: refundAmount,
        metadata: mergedProviderResponse
      }, tx);

      await recordFinancialEntry({
        tx,
        paymentIntent: updatedIntent,
        appointment: updatedIntent.appointment,
        entryType,
        status: newStatus,
        direction: 'debit',
        amount: refundAmount,
        source: updatedIntent.provider || 'midtrans',
        metadata: mergedProviderResponse
      });

      await tx.invoice.updateMany({
        where: { paymentIntentId: updatedIntent.id },
        data: { status: newStatus }
      }).catch(() => null);

      // Create refund record in the DB if it does not exist
      const providerRefundReference = mergedProviderResponse.refund_key || mergedProviderResponse.refund_id || mergedProviderResponse.refund_reference || providerPaymentId || `webhook-ref-${Date.now()}`;
      const existingRefund = await tx.refund.findFirst({
        where: {
          paymentIntentId: updatedIntent.id,
          providerRefundReference: String(providerRefundReference)
        }
      });
      if (!existingRefund) {
        await tx.refund.create({
          data: {
            paymentIntentId: updatedIntent.id,
            refundAmount,
            refundReason: failureReason || mergedProviderResponse.failureReason || 'Webhook/status refund transition',
            refundStatus: 'refunded',
            providerRefundReference: String(providerRefundReference),
            refundRequestedAt: new Date(),
            refundedAt: new Date()
          }
        });
      }

      // Update available balance record to decrement availableAmount
      const whereBalance = updatedIntent.ownerType === 'clinic'
        ? { ownerClinicId: updatedIntent.ownerClinicId }
        : { ownerDentistId: updatedIntent.ownerDentistId };

      // Concurrency protection: Lock balance row
      let balance = await tx.availableBalance.findFirst({ where: whereBalance });
      if (!balance) {
        balance = await tx.availableBalance.create({
          data: {
            ownerType: updatedIntent.ownerType,
            ownerClinicId: updatedIntent.ownerClinicId,
            ownerDentistId: updatedIntent.ownerDentistId,
            availableAmount: 0,
            pendingAmount: 0,
            currency: updatedIntent.currency || 'IDR'
          }
        });
      }
      await tx.$executeRaw`SELECT id FROM available_balances WHERE id = ${balance.id} FOR UPDATE`;

      const isNegative = balance.availableAmount - refundAmount < 0;
      await tx.availableBalance.update({
        where: { id: balance.id },
        data: {
          availableAmount: { decrement: refundAmount }
        }
      });

      // Write a DEBT ledger entry if the balance went negative
      if (isNegative) {
        const debtAmount = Math.abs(balance.availableAmount - refundAmount);
        await tx.financialLedgerEntry.create({
          data: {
            paymentIntentId: updatedIntent.id,
            appointmentId: updatedIntent.appointmentId,
            ownerType: updatedIntent.ownerType,
            ownerClinicId: updatedIntent.ownerClinicId,
            ownerDentistId: updatedIntent.ownerDentistId,
            entryType: 'DEBT',
            status: 'completed',
            direction: 'debit',
            amount: debtAmount,
            source: 'system',
            metadata: { note: 'Available balance went negative after status transition refund' }
          }
        });
      }

      // If clinic dentist appointment, reverse compensation (30% of refundAmount)
      if (updatedIntent.ownerType === 'clinic' && updatedIntent.appointmentId) {
        const appRecord = await tx.appointment.findUnique({
          where: { id: updatedIntent.appointmentId }
        });
        if (appRecord?.dentistId) {
          const profile = await tx.dentistProfile.findFirst({
            where: { userId: appRecord.dentistId }
          });
          if (profile?.dentist_type === 'clinic') {
            const reversedCompensation = Math.round(refundAmount * 0.3);

            await tx.dentistCompensationEntry.create({
              data: {
                appointmentId: updatedIntent.appointmentId,
                paymentIntentId: updatedIntent.id,
                dentistId: appRecord.dentistId,
                clinicId: updatedIntent.ownerClinicId,
                entryType: 'REVERSAL',
                amount: reversedCompensation,
                status: 'paid',
                metadata: { source: 'status_transition_refund' }
              }
            });

            await tx.financialLedgerEntry.create({
              data: {
                paymentIntentId: updatedIntent.id,
                appointmentId: updatedIntent.appointmentId,
                ownerType: 'dentist',
                ownerDentistId: appRecord.dentistId,
                entryType: 'REVERSAL',
                status: 'completed',
                direction: 'debit',
                amount: reversedCompensation,
                source: 'system',
                metadata: { source: 'status_transition_refund' }
              }
            });

            // Decrement the dentist's available balance
            const dentistBalance = await tx.availableBalance.findFirst({
              where: { ownerDentistId: appRecord.dentistId }
            });
            if (dentistBalance) {
              await tx.availableBalance.update({
                where: { id: dentistBalance.id },
                data: {
                  availableAmount: { decrement: reversedCompensation }
                }
              });
            } else {
              await tx.availableBalance.create({
                data: {
                  ownerType: 'dentist',
                  ownerDentistId: appRecord.dentistId,
                  availableAmount: -reversedCompensation,
                  pendingAmount: 0,
                  currency: updatedIntent.currency || 'IDR'
                }
              });
            }
          }
        }
      }
    }

    return {
      paymentIntent: updatedIntent,
      appointmentStatus,
      appointment,
      noOp: false
    };
  };

  if (externalTx) {
    return runUpdates(externalTx);
  }

  const result = await prisma.$transaction(async (tx) => {
    return runUpdates(tx);
  });

  if (result.noOp) {
    return {
      paymentIntent: result.paymentIntent,
      appointmentStatus: result.appointmentStatus || result.appointment?.status || result.paymentIntent.status,
      noOp: true
    };
  }

  const resolvedStatus = result.appointmentStatus || result.appointment?.status || newStatus;
  const commPayload = await syncCommunications(result.appointment, resolvedStatus);

  const eventType = mapStatusToEvent(newStatus);
  await emitAppointmentEvent({
    type: eventType,
    appointmentId: result.appointment?.id?.toString?.() ?? '',
    payload: {
      paymentIntentId: result.paymentIntent.id.toString(),
      status: newStatus,
      ...commPayload
    }
  });

  const realtimePayload = {
    paymentIntentId: result.paymentIntent.id.toString(),
    appointmentId: result.appointment?.id?.toString?.() ?? result.paymentIntent.appointmentId?.toString?.() ?? null,
    status: newStatus,
    appointmentStatus: resolvedStatus,
    ownerType: result.paymentIntent.ownerType,
    ownerClinicId: result.paymentIntent.ownerClinicId?.toString?.() || null,
    ownerDentistId: result.paymentIntent.ownerDentistId?.toString?.() || null,
    amount: result.paymentIntent.amount,
    currency: result.paymentIntent.currency || 'IDR',
    metadata: result.paymentIntent.metadata || {},
    emittedAt: new Date().toISOString()
  };
  emitToUserRooms({
    userIds: [result.appointment?.patientId, result.appointment?.dentistId, result.paymentIntent.ownerDentistId],
    eventName: 'payment:status_updated',
    payload: realtimePayload
  });
  emitToUserRooms({
    userIds: [result.appointment?.patientId, result.appointment?.dentistId, result.paymentIntent.ownerDentistId],
    eventName: 'billing:invoice_updated',
    payload: realtimePayload
  });
  emitToUserRooms({
    userIds: [result.appointment?.patientId, result.appointment?.dentistId, result.paymentIntent.ownerDentistId],
    eventName: 'dashboard:metrics_updated',
    payload: realtimePayload
  });

  return {
    paymentIntent: result.paymentIntent,
    appointmentStatus: resolvedStatus,
    noOp: false
  };
}

